(function(A){Object.assign(A.D,{"G4214":{"l":"πόσος","o":27,"ar":"<f><o>πόσος</o>، <g>-η, -ον</g>،</f> صفة للعدد والمقدار والدرجة إلخ، <s><b>كم</b>، <b>ما أعظم</b>، <b>كم عددًا</b>: <r v=\"Matt.6.23\"></r>، <r v=\"2Cor.7.11\"></r>؛ عن الزمن، <r v=\"Mark.9.21\"></r>؛ المحايد، مطلقًا، <r v=\"Luke.16.5\"></r>، <r v=\"Luke.16.7\"></r>؛ حالة القابل <g>πόσῳ</g> ظرفًا: <b>بكم</b> (كم بالحري)، <r v=\"Matt.12.12\"></r>؛ والتعبير نفسه يليه <g>μᾶλλον</g> (كم بالحري)، <r v=\"Matt.7.11\"></r> <r v=\"Matt.10.25\"></r>، <r v=\"Luke.11.13\"></r> <r v=\"Luke.12.24\"></r>، <r v=\"Luke.12.28\"></r>، <r v=\"Rom.11.12\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Phlm.1.16\"></r>، <r v=\"Heb.9.14\"></r>؛ <g>π. χείρονος τιμωρίας</g> (فكم عقابًا أشرّ)، <r v=\"Heb.10.29\"></r>؛ جمع، <r v=\"Matt.15.34\"></r> <r v=\"Matt.16.9\"></r>، <r v=\"Matt.16.10\"></r> <r v=\"Matt.27.13\"></r>، <r v=\"Mark.6.38\"></r> <r v=\"Mark.8.5\"></r>، <r v=\"Mark.8.19\"></r>، <r v=\"Mark.8.20\"></r> <r v=\"Mark.15.4\"></r>، <r v=\"Luke.15.17\"></r>، <r v=\"Acts.21.20\"></r>.†</s>","en":"<f><o>πόσος</o>, <g>-η, -ον</g>,</f> adj. of number, magnitude, degree, etc., <s><b>how much</b>, <b>how great</b>, <b>how many</b>: <r v=\"Matt.6.23\"></r>, <r v=\"2Cor.7.11\"></r>; of time, <r v=\"Mark.9.21\"></r>; neut., absol., <r v=\"Luke.16.5\"></r>, <r v=\"Luke.16.7\"></r>; dat., <g>πόσῳ</g>, adverbially, <b>how much</b>, <r v=\"Matt.12.12\"></r>; id. seq. <g>μᾶλλον</g>, <r v=\"Matt.7.11\"></r> <r v=\"Matt.10.25\"></r>, <r v=\"Luke.11.13\"></r> <r v=\"Luke.12.24\"></r>, <r v=\"Luke.12.28\"></r>, <r v=\"Rom.11.12\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Phlm.1.16\"></r>, <r v=\"Heb.9.14\"></r>; <g>π. χείρονος τιμωρίας</g>, <r v=\"Heb.10.29\"></r>; pl., <r v=\"Matt.15.34\"></r> <r v=\"Matt.16.9\"></r>, <r v=\"Matt.16.10\"></r> <r v=\"Matt.27.13\"></r>, <r v=\"Mark.6.38\"></r> <r v=\"Mark.8.5\"></r>, <r v=\"Mark.8.19\"></r>, <r v=\"Mark.8.20\"></r> <r v=\"Mark.15.4\"></r>, <r v=\"Luke.15.17\"></r>, <r v=\"Acts.21.20\"></r>.†</s>"},"G4218":{"l":"ποτέ","o":29,"ar":"<f><o>ποτέ</o>،</f> أداة ملحقة، <s n=\"1.\"><b>مرةً</b>، <b>قبلاً</b>، <b>حينًا</b>: عن الماضي، <r v=\"John.9.13\"></r>، <r v=\"Rom.7.9\"></r> <r v=\"Rom.11.30\"></r>، <r v=\"Gal.1.13\"></r>، <r v=\"Gal.1.23\"></r> <r v=\"Gal.2.6\"></r>، <r v=\"Eph.2.2\"></r>، <r v=\"Eph.2.3\"></r>، <r v=\"Eph.2.11\"></r>، <r v=\"Eph.2.13\"></r> <r v=\"Eph.5.8\"></r>، <r v=\"Col.1.21\"></r> <r v=\"Col.3.7\"></r>، <r v=\"1Thess.2.5\"></r>، <r v=\"Titus.3.3\"></r>، <r v=\"Phlm.1.11\"></r>، <r v=\"1Pet.2.10\"></r> <r v=\"1Pet.3.5\"></r>، <r v=\"1Pet.3.20\"></r>؛ <g>ἤδη ποτέ</g>، <b>الآن أخيرًا</b>، <r v=\"Phil.4.10\"></r>؛ عن المستقبل، <r v=\"Luke.22.32\"></r>؛ <g>εἴ πως ἤδη ποτέ</g>، <b>لعلّه الآن أخيرًا</b>، <r v=\"Rom.1.10\"></r>.</s> <s n=\"2.\"><b>قطّ</b>، <b>أبدًا</b>: بعد النفي، <r v=\"Eph.5.29\"></r>، <r v=\"2Pet.1.10\"></r>، <r v=\"2Pet.1.21\"></r>؛ في السؤال، <g>τίς π.</g>، <r v=\"1Cor.9.7\"></r>، <r v=\"Heb.1.5\"></r>، <r v=\"Heb.1.13\"></r>.†</s>","en":"<f><o>ποτέ</o>,</f> enclitic particle, <s n=\"1.\"><b>once</b>, <b>formerly</b>, <b>sometime</b>: of the past, <r v=\"John.9.13\"></r>, <r v=\"Rom.7.9\"></r> <r v=\"Rom.11.30\"></r>, <r v=\"Gal.1.13\"></r>, <r v=\"Gal.1.23\"></r> <r v=\"Gal.2.6\"></r> (Lft., in l.), <r v=\"Eph.2.2\"></r>, <r v=\"Eph.2.3\"></r>, <r v=\"Eph.2.11\"></r>, <r v=\"Eph.2.13\"></r> <r v=\"Eph.5.8\"></r>, <r v=\"Col.1.21\"></r> <r v=\"Col.3.7\"></r>, <r v=\"1Thess.2.5\"></r>, <r v=\"Titus.3.3\"></r>, <r v=\"Phlm.1.11\"></r>, <r v=\"1Pet.2.10\"></r> <r v=\"1Pet.3.5\"></r>, <r v=\"1Pet.3.20\"></r>; <g>ἤδη ποτέ</g>, <b>now at length</b>, <r v=\"Phil.4.10\"></r>; of the fut., <r v=\"Luke.22.32\"></r>; <g>εἴ πως ἤδη ποτέ</g>, <b>if sometime soon at length</b>, <r v=\"Rom.1.10\"></r>.</s> <s n=\"2.\"><b>ever</b>: after a neg., <r v=\"Eph.5.29\"></r>, <r v=\"2Pet.1.10\"></r>, <r v=\"2Pet.1.21\"></r>; in a question, <g>τίς π.</g>, <r v=\"1Cor.9.7\"></r>, <r v=\"Heb.1.5\"></r>, <r v=\"Heb.1.13\"></r>.†</s>"},"G4246":{"l":"πρεσβύτης","o":3,"ar":"<f><o>πρεσβύτης</o>، <g>-ου </g>، الصيغة النثرية لـ<g>πρέσβυς</g> (انظره)،</f> <s n=\"1.\"><b>شيخ، رجل مسنّ</b>: <r v=\"Luke.1.18\"></r>، <r v=\"Titus.2.2\"></r>، <r v=\"Phlm.1.9\"></r> (لكن انظر أدناه).</s> <s n=\"2.\">كما في السبعينية، بمعنى <g>πρεσβευτής</g> أيضًا: <b>سفير</b>: <r v=\"Phlm.1.9\"></r>.†</s>","en":"<f><o>πρεσβύτης</o>, <g>-ου </g> prose form of <g>πρέσβυς</g>, q.v.,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2205\">זָקֵן</h>, <r v=\"Gen.25.8\"></r>, al.; also (= <g>πρεσβευτής</g>), <r v=\"2Chr.32.31\"></r> B<i>1</i> (<h n=\"H3887\">מֵלִיץ</h>), <r v=\"1Macc.14.22\"></r> S, al. (v. Thackeray, <i>Gr.</i>, 97);]</e> </et> <s n=\"1.\"><b>an old man</b>: <r v=\"Luke.1.18\"></r>, <r v=\"Titus.2.2\"></r>, <r v=\"Phlm.1.9\"></r> (R, txt., but v. infr.).</s> <s n=\"2.\">As in LXX, also = <g>πρεσβευτής</g>, <b>an ambassador</b>: <r v=\"Phlm.1.9\"></r> (R, mg., v. Lft. and <i>ICC</i>, in l.).†</s>"},"G4238":{"l":"πράσσω","o":39,"ar":"<f><o>πράσσω</o>،</f> <s n=\"1.\"><b>يعمل</b>، <b>يمارس</b>، <b>ينشغل بـ</b>: <r v=\"Acts.19.19\"></r>، <r v=\"Acts.19.36\"></r>، <r v=\"1Cor.9.17\"></r>؛ <g>τ. ἴδια π.</g>، <b>يمارس أموره الخاصة</b>، <b>يهتم بشأنه</b>، <r v=\"1Thess.4.11\"></r>؛ لازم، <b>يتصرّف</b>، <b>يعمل</b>، <r v=\"Acts.17.7\"></r>.</s> <s n=\"2.\"><b>يُحقِّق</b>، <b>يُحدِث</b>، <b>يُنجِز</b>، <b>يؤدّي</b>: <r v=\"Acts.26.20\"></r>، <r v=\"Acts.26.26\"></r>، <r v=\"Rom.7.15\"></r> <r v=\"Rom.9.11\"></r>، <r v=\"2Cor.5.10\"></r>، <r v=\"Phil.4.9\"></r>؛ <g>νόμον</g>، <r v=\"Rom.2.25\"></r>؛ وعن الأفعال الدنيئة، <b>يرتكب</b>، <b>يفعل</b>: <r v=\"Luke.22.23\"></r> <r v=\"Luke.23.41\"></r>، <r v=\"John.3.20\"></r> <r v=\"John.5.29\"></r>، <r v=\"Acts.3.17\"></r> <r v=\"Acts.5.35\"></r> <r v=\"Acts.16.28\"></r> <r v=\"Acts.25.11\"></r>، <r v=\"Acts.25.25\"></r> <r v=\"Acts.26.9\"></r>، <r v=\"Acts.26.31\"></r>، <r v=\"Rom.1.32\"></r>، <r v=\"Rom.2.1-Rom.2.3\"></r> <r v=\"Rom.7.19\"></r> <r v=\"Rom.13.4\"></r>، <r v=\"1Cor.5.2\"></r>، <r v=\"2Cor.12.21\"></r>، <r v=\"Gal.5.21\"></r>.</s> <s n=\"3.\"><b>يُدير</b>، <b>يتولّى</b>، ومن ثم عن المال، <b>يَستوفي</b>، <b>يجبي</b>: <r v=\"Luke.3.13\"></r> <r v=\"Luke.19.23\"></r>.</s> <s n=\"4.\">انعكاسيًا عن الحال أو الوضع، <b>يكون حاله</b>، <b>يحسن أو يسوء حاله</b>: <r v=\"Eph.6.21\"></r>؛ <g>εὖ π.</g>، <r v=\"Acts.15.29\"></r>.†</s>","en":"<f><o>πράσσω</o>,</f> <et> <e t=\"derivation\">(Att. <g>-ττω</g>, and so <r v=\"Acts.17.7\"></r> Rec.; cf. M, <i>Pr.</i>, 25, 45),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6213\">עשׂה</h>, <h n=\"H6466\">פָּעַל</h>;]</e> </et> <e t=\"derivation\">= Lat <l>agere</l>, as <g>ποιέω</g> (q.v.) = <l>facere</l>,</e> <s n=\"1.\"><b>to do</b>, <b>practise</b>, <b>be engaged in</b>: <r v=\"Acts.19.19\"></r>, <r v=\"Acts.19.36\"></r>, <r v=\"1Cor.9.17\"></r>; <g>τ. ἴδια π.</g>, <b>to mind one's own business</b> (<g>τὰ ἑαυτοῦ</g>, Soph., Plat.), <r v=\"1Thess.4.11\"></r>; intrans., <b>to act</b>, <r v=\"Acts.17.7\"></r>.</s> <s n=\"2.\"><b>to achieve</b>, <b>effect</b>, <b>accomplish</b>, <b>perform</b>: <r v=\"Acts.26.20\"></r>, <r v=\"Acts.26.26\"></r>, <r v=\"Rom.7.15\"></r> <r v=\"Rom.9.11\"></r>, <r v=\"2Cor.5.10\"></r>, <r v=\"Phil.4.9\"></r>; <g>νόμον</g> (<i>ICC</i>, in l.), <r v=\"Rom.2.25\"></r>; of unworthy acts (for wh. usually <g>ποιέω</g> in cl.), <b>to commit</b>, <b>do</b>: <r v=\"Luke.22.23\"></r> <r v=\"Luke.23.41\"></r>, <r v=\"John.3.20\"></r> <r v=\"John.5.29\"></r>, <r v=\"Acts.3.17\"></r> <r v=\"Acts.5.35\"></r> <r v=\"Acts.16.28\"></r> <r v=\"Acts.25.11\"></r>, <r v=\"Acts.25.25\"></r> <r v=\"Acts.26.9\"></r>, <r v=\"Acts.26.31\"></r>, <r v=\"Rom.1.32\"></r> (<i>ICC</i>, in l.), <r v=\"Rom.2.1-Rom.2.3\"></r> <r v=\"Rom.7.19\"></r> <r v=\"Rom.13.4\"></r>, <r v=\"1Cor.5.2\"></r>, <r v=\"2Cor.12.21\"></r>, <r v=\"Gal.5.21\"></r>.</s> <s n=\"3.\"><b>to transact</b>, <b>manage</b>, hence, of payment, <b>to exact</b> (cl.): <r v=\"Luke.3.13\"></r> <r v=\"Luke.19.23\"></r>.</s> <s n=\"4.\">Reflexively, of state or condition, <b>to do</b> or <b>fare</b> (Æsch., Hdt., al.): <r v=\"Eph.6.21\"></r>; <g>εὖ π.</g> (v. M, <i>Pr.</i>, 228 f.), <r v=\"Acts.15.29\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>ποιέω</g>.</sy>"},"G4282":{"l":"προετοιμάζω","o":2,"ar":"<f><o>προ-ετοιμάζω</o>،</f> <s><b>يُعِدّ مسبقًا (سبق فأعدّ)</b>: مع المنصوب للشيء، <r v=\"Rom.9.23\"></r> (<g>οἷς</g> بدلاً من <g>ἅ</g> بالجذب الإعرابي)، <r v=\"Eph.2.10\"></r>.†</s>","en":"<f><o>προ-ετοιμάζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.28.24\"></r> B, <r v=\"Wis.9.8\"></r>*;]</e> </et> <s><b>to prepare before</b>: c. acc. rei, <r v=\"Rom.9.23\"></r> (<g>οἷς</g> for <g>ἅ</g> by attraction), <r v=\"Eph.2.10\"></r>.†</s>"},"G4253":{"l":"πρό","o":47,"ar":"<f><o>πρό</o>،</f> حرف جر مع المضاف إليه، <s><b>قبل</b>، <b>أمام</b>؛ <s n=\"(a)\">عن المكان: <r v=\"Acts.12.6\"></r>، <r v=\"Acts.12.14\"></r> <r v=\"Acts.14.13\"></r>، <r v=\"Jas.5.9\"></r>؛ <g>π. προσώπου</g> (= العبرية <h n=\"H6440\">לִפְנֵי</h>، <r v=\"Deut.3.18\"></r>، <r v=\"Mal.3.1\"></r>، وفي مواضع أخرى)، <r v=\"Matt.11.10\"></r>، <r v=\"Mark.1.2\"></r>، <r v=\"Luke.1.76\"></r> <r v=\"Luke.7.27\"></r> <r v=\"Luke.9.52\"></r> <r v=\"Luke.10.1\"></r>، <r v=\"Acts.14.13\"></r>؛</s> <s n=\"(b)\">عن الزمن: <r v=\"Matt.8.29\"></r> <r v=\"Matt.24.38\"></r>، <r v=\"Luke.11.38\"></r> <r v=\"Luke.21.12\"></r>، <r v=\"John.11.55\"></r> <r v=\"John.13.1\"></r> <r v=\"John.17.24\"></r>، <r v=\"Acts.5.36\"></r> <r v=\"Acts.21.38\"></r>، <r v=\"1Cor.2.7\"></r> <r v=\"1Cor.4.5\"></r>، <r v=\"Eph.1.4\"></r>، <r v=\"Col.1.17\"></r>، <r v=\"2Tim.1.9\"></r> <r v=\"2Tim.4.21\"></r>، <r v=\"Titus.1.2\"></r>، <r v=\"Heb.11.5\"></r>، <r v=\"1Pet.1.20\"></r>، <r v=\"Jude.1.25\"></r>؛ <g>π. ἐτῶν δεκατεσσάρων</g>، <b>قبل أربع عشرة سنة</b>، <r v=\"2Cor.12.2\"></r>؛ <g>π. προσώπου</g> (انظر أعلاه)، <r v=\"Acts.13.24\"></r>؛ مع مضاف إليه الشخص، <r v=\"Matt.5.12\"></r>، <r v=\"John.5.7\"></r> <r v=\"John.10.8\"></r>، <r v=\"Rom.16.7\"></r>، <r v=\"Gal.1.17\"></r>؛ مع المصدر المعرَّف بأداة التعريف في حالة الجر (= <g>πρίν</g>)، <r v=\"Matt.6.8\"></r>، <r v=\"Luke.2.21\"></r> <r v=\"Luke.22.15\"></r>، <r v=\"John.1.49\"></r> <r v=\"John.13.19\"></r> <r v=\"John.17.5\"></r>، <r v=\"Acts.23.15\"></r>، <r v=\"Gal.2.12\"></r> <r v=\"Gal.3.23\"></r>؛ وكما عند الكتّاب المتأخرين (قارن <r v=\"Amos.1.1\"></r>، <r v=\"2Macc.15.36\"></r>)، <g>πρὸ ἓξ ἡμέρας τοῦ πασχα</g>، <b>قبل الفصح بستة أيام</b>، <r v=\"John.12.1\"></r>؛</s> <s n=\"(c)\">عن التفضيل: <g>π. πάντων</g>، <b>قبل كل شيء</b>، <r v=\"Jas.5.12\"></r>، <r v=\"1Pet.4.8\"></r>؛</s> <s n=\"(d)\">في التركيب، <s n=\"α\">مع الاسم، للدلالة على الموضع أمام: <g>προαύλιον</g>، <g>πρόδρομος</g>؛ والأسبقية في الرتبة أو الترتيب، <g>προπάτωρ</g>؛ والاستباق، <g>πρόγνωσις</g>، <g>πρόνοια</g>؛</s> <s n=\"β\">مع الصفة، للتوكيد والشدة، <g>πρόδηλος</g>؛</s> <s n=\"γ\">مع الفعل، عن المكان، <g>προάγω</g>، <g>προβαίνω</g>؛ وعن التفضيل، <g>προαιρέομαι</g>.†</s> </s> </s>","en":"<f><o>πρό</o>,</f> prep. c. gen., <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6440\">לִפְנֵי</h>;]</e> </et> <s><b>before</b>; <s n=\"(a)\">of place: <r v=\"Acts.12.6\"></r>, <r v=\"Acts.12.14\"></r> <r v=\"Acts.14.13\"></r>, <r v=\"Jas.5.9\"></r>; <g>π. προσώπου</g> (= Heb. <h n=\"H6440\">לִפְנֵי</h>, <r v=\"Deut.3.18\"></r>, <r v=\"Mal.3.1\"></r>, al.; Bl., § 40, 9), <r v=\"Matt.11.10\"></r>, <r v=\"Mark.1.2\"></r>, <r v=\"Luke.1.76\"></r> <r v=\"Luke.7.27\"></r> <r v=\"Luke.9.52\"></r> <r v=\"Luke.10.1\"></r>, <r v=\"Acts.14.13\"></r>;</s> <s n=\"(b)\">of time: <r v=\"Matt.8.29\"></r> <r v=\"Matt.24.38\"></r>, <r v=\"Luke.11.38\"></r> <r v=\"Luke.21.12\"></r>, <r v=\"John.11.55\"></r> <r v=\"John.13.1\"></r> <r v=\"John.17.24\"></r>, <r v=\"Acts.5.36\"></r> <r v=\"Acts.21.38\"></r>, <r v=\"1Cor.2.7\"></r> <r v=\"1Cor.4.5\"></r>, <r v=\"Eph.1.4\"></r>, <r v=\"Col.1.17\"></r>, <r v=\"2Tim.1.9\"></r> <r v=\"2Tim.4.21\"></r>, <r v=\"Titus.1.2\"></r>, <r v=\"Heb.11.5\"></r>, <r v=\"1Pet.1.20\"></r>, <r v=\"Jude.1.25\"></r>; <g>π. ἐτῶν δεκατεσσάρων</g>, <b>fourteen years ago</b>, <r v=\"2Cor.12.2\"></r>; <g>π. προσώπου</g> (v. supr.), <r v=\"Acts.13.24\"></r>; c. gen. pers., <r v=\"Matt.5.12\"></r>, <r v=\"John.5.7\"></r> <r v=\"John.10.8\"></r>, <r v=\"Rom.16.7\"></r>, <r v=\"Gal.1.17\"></r>; c. gen. art. inf. (= <g>πρίν</g>; M, <i>Pr.</i>, 100; Bl., § 69, 7), <r v=\"Matt.6.8\"></r>, <r v=\"Luke.2.21\"></r> <r v=\"Luke.22.15\"></r>, <r v=\"John.1.49\"></r> <r v=\"John.13.19\"></r> <r v=\"John.17.5\"></r>, <r v=\"Acts.23.15\"></r>, <r v=\"Gal.2.12\"></r> <r v=\"Gal.3.23\"></r>; as in late writers (resembling a Latin idiom but independent of it; B1., § 40, 5; M, <i>Pr.</i>, 100 f.; cf. <r v=\"Amos.1.1\"></r>, <r v=\"2Macc.15.36\"></r>, and for other exx., Soph., <i>Lex.</i>, s.v.), <g>πρὸ ἓξ ἡμέρας τοῦ πασχα</g>, <b>on the sixth day bef. the Passover</b>, <r v=\"John.12.1\"></r>;</s> <s n=\"(c)\">of preference: <g>π. πάντων</g>, <r v=\"Jas.5.12\"></r>, <r v=\"1Pet.4.8\"></r>;</s> <s n=\"(d)\">in compos., <s n=\"α\">c. subst., of position before: <g>προαύλιον</g>, <g>πρόδρομος</g>; priority of rank or order, <g>προπάτωρ</g>; anticipation, <g>πρόγνωσις</g>, <g>πρόνοια</g>;</s> <s n=\"β\">c. adj., intensity, <g>πρόδηλος</g>;</s> <s n=\"γ\">c. verb., of place, <g>προάγω</g>, <g>προβαίνω</g>; of preference, <g>προαιρέομαι</g>.†</s> </s> </s>"},"G4228":{"l":"πούς","o":93,"ar":"<f><o>πούς</o>، <g>ποδός, ὁ</g>،</f> <s><b>قَدَم</b>، <b>رِجْل</b>، للبشر والبهائم على السواء: <r v=\"Matt.4.6\"></r><i>(السبعينية)</i>، <r v=\"Mark.9.45\"></r>، <r v=\"Luke.1.79\"></r>، <r v=\"John.11.44\"></r>، <r v=\"Acts.7.5\"></r>، وفي مواضع أخرى؛ <g>ὑπο τοὺς π.</g>، <r v=\"Rom.16.20\"></r>، <r v=\"1Cor.15.25\"></r>، <r v=\"1Cor.15.27\"></r>، <r v=\"Eph.1.22\"></r>، <r v=\"Heb.2.8\"></r>؛ <g>ὑποκάτω τῶν π.</g>، <r v=\"Matt.22.44\"></r><i>(السبعينية)</i>؛ <g>πρὸς</g> (<g>παρὰ</g>) <g>τοὺς π.</g>، <r v=\"Mark.5.22\"></r>، <r v=\"Luke.8.41\"></r>، وفي مواضع أخرى؛ مجازيًا، <r v=\"Matt.15.30\"></r>، <r v=\"Luke.10.39\"></r>، <r v=\"Acts.5.2\"></r>، وفي مواضع أخرى؛ <g>ἔμπροσθεν τῶν π.</g>، <r v=\"Rev.3.9\"></r> <r v=\"Rev.19.10\"></r>، وفي مواضع أخرى؛ <g>ἐπὶ τοὺς π.</g>، <r v=\"Acts.10.25\"></r>. وكنايةً عن الشخص المتحرك (<r v=\"Ps.119.101\"></r>): <r v=\"Luke.1.79\"></r>، <r v=\"Acts.5.9\"></r>، <r v=\"Rom.3.15\"></r> <r v=\"Rom.10.15\"></r>، <r v=\"Heb.12.13\"></r>.</s>","en":"<f><o>πούς</o>, <g>ποδός, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7272\">רֶגֶל</h>;]</e> </et> <s><b>a foot</b>, both of men and beasts: <r v=\"Matt.4.6\"></r><i>(LXX)</i>, <r v=\"Mark.9.45\"></r>, <r v=\"Luke.1.79\"></r>, <r v=\"John.11.44\"></r>, <r v=\"Acts.7.5\"></r>, al.; <g>ὑπο τοὺς π.</g>, <r v=\"Rom.16.20\"></r>, <r v=\"1Cor.15.25\"></r>, <r v=\"1Cor.15.27\"></r>, <r v=\"Eph.1.22\"></r>, <r v=\"Heb.2.8\"></r>; <g>ὑποκάτω τῶν π.</g>, <r v=\"Matt.22.44\"></r><i>(LXX)</i>; <g>πρὸς</g> (<g>παρὰ</g>) <g>τοὺς π.</g>, <r v=\"Mark.5.22\"></r>, <r v=\"Luke.8.41\"></r>, al.; fig., <r v=\"Matt.15.30\"></r>, <r v=\"Luke.10.39\"></r>, <r v=\"Acts.5.2\"></r>, al.; <g>ἔμπροσθεν τῶν π.</g>, <r v=\"Rev.3.9\"></r> <r v=\"Rev.19.10\"></r>, al.; <g>ἐπὶ τοὺς π.</g>, <r v=\"Acts.10.25\"></r>. By meton., of a person in motion (<r v=\"Ps.119.101\"></r>): <r v=\"Luke.1.79\"></r>, <r v=\"Acts.5.9\"></r>, <r v=\"Rom.3.15\"></r> <r v=\"Rom.10.15\"></r>, <r v=\"Heb.12.13\"></r>.</s>"},"G4286":{"l":"πρόθεσις","o":12,"ar":"<f><o>πρό-θεσις</o>، <g>-εως, ἡ</g>،</f> <s n=\"1.\"><b>تقديم، وضع الشيء أمامًا (عرض)</b> : <g>οἱ ἄρτοι τῆς π.</g> (قارن السبعينية، <r v=\"Exod.40.4\"></r>، <r v=\"Exod.40.23\"></r>، <r v=\"1Chr.9.32\"></r>، <r v=\"2Chr.4.19\"></r>، <r v=\"1Macc.1.22\"></r>، <r v=\"2Macc.3.8\"></r>، وفي موضع آخر <g>ἄρτοι ἐνώπιοι</g>، <r v=\"Exod.25.29\"></r>؛ <g>οἱ ἄ. τοῦ προσώπου</g>، <r v=\"Neh.10.33\"></r>)، <r v=\"Matt.12.4\"></r>، <r v=\"Mark.2.26\"></r>، <r v=\"Luke.6.4\"></r>؛ <g>ἡ π. τῶν ἄρτων</g>، <r v=\"Heb.9.2\"></r>.</s> <s n=\"2.\"><b>قصد</b>، <b>عزم</b> (<r v=\"2Macc.3.8\"></r>): <r v=\"Acts.11.23\"></r> <r v=\"Acts.27.13\"></r>، <r v=\"Rom.8.28\"></r> <r v=\"Rom.9.11\"></r>، <r v=\"Eph.1.11\"></r> <r v=\"Eph.3.11\"></r>، <r v=\"2Tim.1.9\"></r> <r v=\"2Tim.3.10\"></r>.†</s>","en":"<f><o>πρό-θεσις</o>, <g>-εως, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.40.4\"></r>, <r v=\"Exod.40.23\"></r> (<h n=\"H6187\">עֵרֶךְ</h>), <r v=\"1Chr.9.32\"></r>, al. (<h n=\"H4635\">מַעֲרֶכֶת</h>), <r v=\"2Chr.4.19\"></r> (<h n=\"H6440\">פָּנִים</h>), <r v=\"1Macc.1.22\"></r>, <r v=\"2Macc.3.8\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a setting forth</b> (Plat., Plut., al.): <g>οἱ ἄρτοι τῆς π.</g> (cf. LXX, <r v=\"Exod.40.4\"></r>, <r v=\"Exod.40.23\"></r>, <r v=\"1Chr.9.32\"></r>, <r v=\"2Chr.4.19\"></r>, <r v=\"1Macc.1.22\"></r>, <r v=\"2Macc.3.8\"></r>, elsewhere <g>ἄρτοι ἐνώπιοι</g>, <r v=\"Exod.25.29\"></r>; <g>οἱ ἄ. τοῦ προσώπου</g>, <r v=\"Neh.10.33\"></r>), <r v=\"Matt.12.4\"></r>, <r v=\"Mark.2.26\"></r>, <r v=\"Luke.6.4\"></r>; <g>ἡ π. τῶν ἄρτων</g>, <r v=\"Heb.9.2\"></r>.</s> <s n=\"2.\"><b>a purpose</b> (Mist., Polyb., al.; <r v=\"2Macc.3.8\"></r>): <r v=\"Acts.11.23\"></r> <r v=\"Acts.27.13\"></r>, <r v=\"Rom.8.28\"></r> <r v=\"Rom.9.11\"></r>, <r v=\"Eph.1.11\"></r> <r v=\"Eph.3.11\"></r>, <r v=\"2Tim.1.9\"></r> <r v=\"2Tim.3.10\"></r>.†</s>"},"G4270":{"l":"προγράφω","o":4,"ar":"<f><o>προ-γράφω</o>،</f> <s n=\"1.\"><b>يكتب سابقًا</b>: <r v=\"Rom.15.4\"></r>، <r v=\"Eph.3.3\"></r>، <r v=\"Jude.1.4\"></r>.</s> <s n=\"2.\"><b>يكتب علانيةً</b>، <b>يعلّق إعلانًا</b>، <b>يُعلن</b>: <r v=\"Gal.3.1\"></r>.</s> <s n=\"3.\">= <g>ζωγραφέω</g>، <b>يصوِّر</b>، <b>يرسم</b>: <r v=\"Gal.3.1\"></r>.†</s>","en":"<f><o>προ-γράφω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.3.3\"></r> <i>cod.</i>, <r v=\"1Macc.10.36\"></r>*;]</e> </et> <s n=\"1.\"><b>to write before</b>: <r v=\"Rom.15.4\"></r>, <r v=\"Eph.3.3\"></r>, <r v=\"Jude.1.4\"></r>.</s> <s n=\"2.\"><b>to write in public</b>, <b>placard</b>, <b>proclaim</b> (Dem., Plut., al.): <r v=\"Gal.3.1\"></r> (Lft., in l.).</s> <s n=\"3.\">= <g>ζωγραφέω</g>, <b>to pourtray</b>, <b>depict</b>: <r v=\"Gal.3.1\"></r> (Syr. Pesh., Chrys.; Field, <i>Notes</i>, 189; <i>CGT</i>, in l.).†</s>"},"G4205":{"l":"πόρνος","o":10,"ar":"<f>** <o>πόρνος</o>، <g>-ου, ὁ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>رجل يبغي</b>، <b>بغيّ من الذكور</b>.</s> <s n=\"2.\"><b>زانٍ</b>: <r v=\"1Cor.5.9-1Cor.5.11\"></r> <r v=\"1Cor.6.9\"></r>، <r v=\"Eph.5.5\"></r>، <r v=\"1Tim.1.10\"></r>، <r v=\"Heb.12.15\"></r> <r v=\"Heb.13.4\"></r>، <r v=\"Rev.21.8\"></r> <r v=\"Rev.22.15\"></r>.†</s>","en":"<f>** <o>πόρνος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.23.16-Sir.23.18\"></r>*;]</e> </et> <s n=\"1.\"><b>a male prostitute</b> (Xen., al.).</s> <s n=\"2.\"><b>a fornicator</b>: <r v=\"1Cor.5.9-1Cor.5.11\"></r> <r v=\"1Cor.6.9\"></r>, <r v=\"Eph.5.5\"></r>, <r v=\"1Tim.1.10\"></r>, <r v=\"Heb.12.15\"></r> <r v=\"Heb.13.4\"></r>, <r v=\"Rev.21.8\"></r> <r v=\"Rev.22.15\"></r>.†</s>"},"G4243":{"l":"πρεσβεύω","o":2,"ar":"<f>* <o>πρεσβεύω</o></f> <s n=\"1.\"><b>يكون الأكبر سنًّا</b>، <b>يتقدّم في المرتبة</b>.</s> <s n=\"2.\"><b>يكون سفيرًا</b>، <b>يسعى كسفير</b> (انظر تحت مدخل <g>πρεσβύτης</g>): <r v=\"2Cor.5.20\"></r>، <r v=\"Eph.6.20\"></r>.†</s>","en":"<f>* <o>πρεσβεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>πρέσβυς</g>),</e> </et> <s n=\"1.\"><b>to be the elder</b>, <b>to take precedence</b>.</s> <s n=\"2.\"><b>to be an ambassador</b> (v.s. <g>πρεσβύτης</g>): <r v=\"2Cor.5.20\"></r>, <r v=\"Eph.6.20\"></r>.†</s>"},"G4236":{"l":"πρᾳότης","o":9,"ar":"<f><o>πρᾳότης</o>، <g>πραότης</g>، انظر تحت مدخل <g>πραΰτης</g>.</f>","en":"<f><o>πρᾳότης</o>, <g>πραότης</g>, v.s. <g>πραΰτης</g>.</f>"},"G4202":{"l":"πορνεία","o":25,"ar":"<f><o>πορνεία</o>، <g>-ας, ἡ</g></f> <s><b>زنى</b>: <r v=\"Acts.15.20\"></r>، <r v=\"Acts.15.29\"></r> <r v=\"Acts.21.25\"></r>، <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.6.13\"></r>، <r v=\"1Cor.6.18\"></r>، <r v=\"2Cor.12.21\"></r>، <r v=\"Gal.5.19\"></r>، <r v=\"Eph.5.3\"></r>، <r v=\"Col.3.5\"></r>، <r v=\"1Thess.4.3\"></r>، <r v=\"Rev.9.21\"></r>؛ الجمع، <r v=\"1Cor.7.2\"></r>؛ مُميَّزًا عن <g>μοιχεία</g> (الفسق)، <r v=\"Matt.15.19\"></r>، <r v=\"Mark.7.21\"></r>؛ = <g>μοιχεία</g> (<r v=\"Amos.8.17\"></r>، <r v=\"Sir.23.23\"></r>، وفي مواضع أخرى)، <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.9\"></r>. ومجازيًا (عن عبادة الأوثان: <r v=\"Deut.23.2\"></r>، <r v=\"Hos.1.2\"></r>): <r v=\"John.8.41\"></r>، وهكذا ربما، <r v=\"Rev.2.21\"></r> <r v=\"Rev.14.18\"></r> <r v=\"Rev.17.2\"></r>، <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.3\"></r> <r v=\"Rev.19.2\"></r>.†</s>","en":"<f><o>πορνεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πορνεύω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2183\">זְנוּנִים</h>, <h n=\"H8457\">תַּזְנוּת</h> and cogn. forms;]</e> </et> <s><b>fornication</b>: <r v=\"Acts.15.20\"></r>, <r v=\"Acts.15.29\"></r> <r v=\"Acts.21.25\"></r>, <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.6.13\"></r>, <r v=\"1Cor.6.18\"></r>, <r v=\"2Cor.12.21\"></r>, <r v=\"Gal.5.19\"></r>, <r v=\"Eph.5.3\"></r>, <r v=\"Col.3.5\"></r>, <r v=\"1Thess.4.3\"></r> (Lft., <i>Notes</i>, 53), <r v=\"Rev.9.21\"></r>; pl. (v. WM, 220; Bl., § 32, 6), <r v=\"1Cor.7.2\"></r>; disting. from <g>μοιχεία</g>, <r v=\"Matt.15.19\"></r>, <r v=\"Mark.7.21\"></r>; = <g>μοιχεία</g> (<r v=\"Amos.8.17\"></r>, <r v=\"Sir.23.23\"></r>, al.), <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.9\"></r>. Metaph. (of idolatry: <r v=\"Deut.23.2\"></r>, <r v=\"Hos.1.2\"></r>): <r v=\"John.8.41\"></r> (Westc., in l.), and so perh. (Thayer-Grimm, s.v.; but v. Swete, in ll.), <r v=\"Rev.2.21\"></r> <r v=\"Rev.14.18\"></r> <r v=\"Rev.17.2\"></r>, <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.3\"></r> <r v=\"Rev.19.2\"></r>.†</s>"},"G4276":{"l":"προελπίζω","o":1,"ar":"<f>*† <o>προ-ελπίζω</o>،</f> <s><b>يرجو مسبقًا (سبق فرجا)</b>: يليه <g>ἐν</g>، <r v=\"Eph.1.12\"></r>.†</s>","en":"<f>*† <o>προ-ελπίζω</o>,</f> <s><b>to hope before</b>: seq. <g>ἐν</g>, <r v=\"Eph.1.12\"></r>.†</s>"},"G4241":{"l":"πρέπω","o":7,"ar":"<f><o>πρέπω</o>،</f> <s n=\"1.\"><b>يُرى بوضوح</b>، <b>يظهر جليًّا</b>.</s> <s n=\"2.\"><b>يُشبه</b>.</s> <s n=\"3.\"><b>يليق</b> أو <b>يحسُن</b>، <b>يناسب</b>: مع القابل، <r v=\"Heb.7.26\"></r>، <r v=\"1Tim.2.10\"></r>، <r v=\"Titus.2.1\"></r>؛ غير شخصي، مع القابل، <r v=\"Eph.5.3\"></r>؛ ونفسه يليه المصدر، <r v=\"Heb.2.10\"></r>؛ <g>πρέπον ἐστίν</g>، مع قابل الشخص والمصدر، <r v=\"Matt.3.15\"></r>؛ مع المنصوب والمصدر، <r v=\"1Cor.11.13\"></r> .†</s>","en":"<f><o>πρέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.93.5\"></r> (<h n=\"H4998\">נאה</h> pi.), etc.;]</e> </et> <s n=\"1.\"><b>to be clearly seen</b>.</s> <s n=\"2.\"><b>to resemble</b>.</s> <s n=\"3.\"><b>to be fitting</b> or <b>becoming</b>, <b>to suit</b>: c. dat., <r v=\"Heb.7.26\"></r>, <r v=\"1Tim.2.10\"></r>, <r v=\"Titus.2.1\"></r>; impers., c. dat., <r v=\"Eph.5.3\"></r>; id. seq. inf., <r v=\"Heb.2.10\"></r>; <g>πρέπον ἐστίν</g>, c. dat. pers. et inf., <r v=\"Matt.3.15\"></r>; c. acc. et inf., <r v=\"1Cor.11.13\"></r> (v. Bl., § 72, 5).†</s>"},"G4281":{"l":"προέρχομαι","o":9,"ar":"<f><o>προ-έρχομαι</o>،</f> <s n=\"1.\"><b>يتقدم</b>، <b>يمضي قُدُمًا</b>، <b>يسير إلى الأمام</b>: يليه <g>μικρόν</g>، <r v=\"Matt.26.39\"></r> و<r v=\"Mark.14.35\"></r>؛ <g>ῥύμην μίαν</g>، <r v=\"Acts.12.10\"></r>.</s> <s n=\"2.\">عن الموضع النسبي، <b>يسبق</b>، <b>يتقدّم أمام</b>: مع المضاف إليه (<r v=\"Jdt.2.19\"></r>)؛ مع المنصوب للأشخاص، <r v=\"Luke.22.47\"></r>؛ يليه <g>ἐνώπιον</g>، <r v=\"Luke.1.17\"></r> (قارن <r v=\"Gen.33.3\"></r>).</s> <s n=\"3.\">للزمان، <b>يسبق</b> أو <b>يتقدم مسبقًا</b>: <r v=\"Acts.20.5\"></r>، <r v=\"Acts.20.13\"></r>، <r v=\"2Cor.9.5\"></r>؛ مع المنصوب للأشخاص (= <g>φθάνω</g>)، <r v=\"Mark.6.33\"></r>.†</s>","en":"<f><o>προ-έρχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.33.3\"></r>, <r v=\"Gen.33.14\"></r> R (<h n=\"H5674\">עבר</h>), <r v=\"Jdt.2.19\"></r>, <r v=\"Sir.32.10\"></r>, al;]</e> </et> <s n=\"1.\"><b>to go forward</b>, <b>go on</b>, <b>advance</b>: seq. <g>μικρόν</g>, <r v=\"Matt.26.39\"></r> and <r v=\"Mark.14.35\"></r> (WH, mg., <g>προσελθών</g>): <g>ῥύμην μίαν</g> (cf. Plat., <i>Rep.</i>, i, 328e), <r v=\"Acts.12.10\"></r>.</s> <s n=\"2.\">Of relative position, <b>to go before</b>, <b>precede</b>: c. gen. (cl.; <r v=\"Jdt.2.19\"></r>); c. acc. pers. (not cl.), <r v=\"Luke.22.47\"></r> (c. gen., Rec.); seq. <g>ἐνώπιον</g>, <r v=\"Luke.1.17\"></r> (cf. <r v=\"Gen.33.3\"></r>).</s> <s n=\"3.\">Of time, <b>to go before</b> or <b>in advance</b>: <r v=\"Acts.20.5\"></r>, <r v=\"Acts.20.13\"></r> (WH, mg., R, mg.), <r v=\"2Cor.9.5\"></r>; c. acc. pers. (= cl. <g>φθάνω</g>), <r v=\"Mark.6.33\"></r>.†</s>"},"G4229":{"l":"πρᾶγμα","o":11,"ar":"<f><o>πρᾶγμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">ما قد عُمل، <b>عمل</b>، <b>فعل</b>: <r v=\"Luke.1.1\"></r>، <r v=\"Acts.5.4\"></r>، <r v=\"2Cor.7.11\"></r>، <r v=\"Heb.6.18\"></r>.</s> <s n=\"2.\">ما يُعمل (مثل اللاتينية <l>res</l>)، ومن ثَمَّ، <b>شيء</b>، <b>أمر</b>، <b>شأن</b>: <r v=\"Matt.18.19\"></r>، <r v=\"Rom.16.2\"></r>، <r v=\"1Thess.4.6\"></r>، <r v=\"Heb.10.1\"></r> <r v=\"Heb.11.1\"></r>، <r v=\"Jas.3.16\"></r>؛ بالمعنى القضائي، <b>دعوى</b>: <r v=\"1Cor.6.1\"></r>.†</s>","en":"<f><o>πρᾶγμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πράσσω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1697\">דָּבָר</h>;]</e> </et> <s n=\"1.\">that which has been done, <b>a deed</b>, <b>act</b>: <r v=\"Luke.1.1\"></r>, <r v=\"Acts.5.4\"></r>, <r v=\"2Cor.7.11\"></r>, <r v=\"Heb.6.18\"></r>.</s> <s n=\"2.\">That which is being done (like Lat. <l>res</l>), hence, <b>a thing</b>, <b>matter</b>, <b>affair</b>: <r v=\"Matt.18.19\"></r>, <r v=\"Rom.16.2\"></r>, <r v=\"1Thess.4.6\"></r> (v. M, <i>Th.</i>, in l.), <r v=\"Heb.10.1\"></r> <r v=\"Heb.11.1\"></r>, <r v=\"Jas.3.16\"></r>; in forensic sense (as freq. in <g>π.</g>, v. Deiss., <i>BS</i>, 233), <b>a law-suit</b>: <r v=\"1Cor.6.1\"></r>.†</s>"},"G4232":{"l":"πραιτώριον","o":8,"ar":"<f>*† <o>πραιτώριον</o>، <g>-ου, τό</g>، (اللاتينية <l>prætorium</l>)،</f> <s n=\"1.\">أصلاً: <b>مقر القيادة</b> في معسكر روماني.</s> <s n=\"2.\"><b>دار الولاية</b> أو <b>المقر</b> الرسمي لوالي الإقليم: <r v=\"Matt.27.27\"></r>، <r v=\"Mark.15.16\"></r>، <r v=\"John.18.28\"></r>، <r v=\"John.18.33\"></r> <r v=\"John.19.9\"></r>؛ <g>τ. π. τ. Ἡρῴδου</g>، <r v=\"Acts.23.35\"></r>.</s> <s n=\"3.\"><b>الحرس الإمبراطوري (البريتوري)</b>: <r v=\"Phil.1.13\"></r>.†</s>","en":"<f>*† <o>πραιτώριον</o>, <g>-ου, τό</g>, (Lat. <l>prætorium</l>),</f> <s n=\"1.\"><b>headquarters</b> in a Roman camp.</s> <s n=\"2.\">The <b>palace</b> or official <b>residence</b> of the Governor of a province: <r v=\"Matt.27.27\"></r>, <r v=\"Mark.15.16\"></r> (v. Swete, in l.), <r v=\"John.18.28\"></r>, <r v=\"John.18.33\"></r> <r v=\"John.19.9\"></r>; <g>τ. π. τ. Ἡρῴδου</g>, <r v=\"Acts.23.35\"></r>.</s> <s n=\"3.\"><b>the Prætorian Guard</b>: <r v=\"Phil.1.13\"></r> (v. Lft., in l.; <i>ICC</i>, 51 f.).†</s>"},"G4284":{"l":"προέχω","o":1,"ar":"<f><o>προ-έχω</o>،</f> <s n=\"1.\">متعدٍّ، <b>يمسك أمام</b>؛ الصيغة الوسطى، <b>يمسك شيئًا أمام نفسه</b>، ومن ثَمَّ، مجازيًا، <b>يعتذر، يتذرَّع</b>: <r v=\"Rom.3.9\"></r>، بحسب هامش الترجمة المنقحة.</s> <s n=\"2.\">لازم <s n=\"(a)\"><b>يبرز، يمتد إلى الأمام</b>؛</s> <s n=\"(b)\">في الجري، <b>يسبق</b>، ومن ثَمَّ، مجازيًا، <b>يفوق، يتفوق</b>: المبني للمجهول، <r v=\"Rom.3.9\"></r>، بحسب متن الترجمة المنقحة.†</s> </s>","en":"<f><o>προ-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.27.6\"></r> A (<h n=\"H2388\">חזק</h> hi.)*;]</e> </et> <s n=\"1.\">Trans., <b>to hold before</b>; mid., <b>to hold something before oneself</b> (Hdt.), hence, metaph., <b>to excuse oneself</b>: <r v=\"Rom.3.9\"></r>, R, mg. (but v. Field, <i>Notes</i>, 152 f.; Lft., <i>Notes</i>, 266 f.; <i>ICC</i> and Vau., in l.).</s> <s n=\"2.\">Intrans. <s n=\"(a)\"><b>to project</b>;</s> <s n=\"(b)\">in running, <b>to have the start</b>, hence, metaph., <b>to excel</b>: pass., <r v=\"Rom.3.9\"></r>, R, txt. (v. reff. supr.).†</s> </s>"},"G4297":{"l":"προκοπή","o":3,"ar":"<f>**† <o>προ-κοπή</o>، <g>-ῆς, ἡ</g></f> <s><b>تقدُّم</b> (أصلاً في السفر، ثم بوجه عام): <r v=\"Phil.1.12\"></r>، <r v=\"Phil.1.25\"></r>، <r v=\"1Tim.4.15\"></r>.†</s>","en":"<f>**† <o>προ-κοπή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προκόπτω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.51.17\"></r>, <r v=\"2Macc.8.8\"></r>*;]</e> </et> <s><b>progress</b> (prop., on a journey, then generally): <r v=\"Phil.1.12\"></r>, <r v=\"Phil.1.25\"></r>, <r v=\"1Tim.4.15\"></r> (condemned by Atticists, v. Rutherford, <i>NPhr.</i>, 158).†</s>"},"G4230":{"l":"πραγματία","o":1,"ar":"<f><o>πραγματία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>اجتهاد دقيق</b>، <b>عمل شاق</b>.</s> <s n=\"2.\"><b>عمل، شغل</b>، <b>مهنة، مشاغل</b>: في الجمع، <r v=\"2Tim.2.4\"></r>.†</s>","en":"<f><o>πραγματία</o> (Rec. <g>-εία</g>, as in cl.), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πραγματεύομαι</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2827\">חֵשֶׁל</h>, etc.;]</e> </et> <s n=\"1.\"><b>careful application</b>, <b>hard work</b>.</s> <s n=\"2.\"><b>business</b>, <b>occupation</b>: pl., <r v=\"2Tim.2.4\"></r>.†</s>"},"G4279":{"l":"προεπαγγέλλω","o":2,"ar":"<f>*† <o>προ-επ-αγγέλλω</o>،</f> <s><b>يعلن مسبقًا</b>. الصيغة الوسطى، <b>يَعِد مسبقًا (سبق فوعد)</b>: مع المنصوب للأشياء، <r v=\"Rom.1.2\"></r>، <r v=\"2Cor.9.5\"></r>.†</s>","en":"<f>*† <o>προ-επ-αγγέλλω</o>,</f> <s><b>to announce before</b>. Mid., <b>to promise before</b>: c. acc. rei, <r v=\"Rom.1.2\"></r>, <r v=\"2Cor.9.5\"></r> (Dio. Cass.).†</s>"},"G4283":{"l":"προευαγγελίζομαι","o":1,"ar":"<f>*† <o>προ-ευαγγελίζομαι</o>،</f> <s><b>يبشّر سابقًا</b>: <r v=\"Gal.3.8\"></r>.†</s>","en":"<f>*† <o>προ-ευαγγελίζομαι</o>,</f> <s><b>to announce glad tidings beforehand</b>: <r v=\"Gal.3.8\"></r>.†</s>"},"G4254":{"l":"προάγω","o":20,"ar":"<f><o>προ-άγω</o>،</f> <s n=\"1.\">أصلاً متعدٍّ: <b>يقود</b>، <b>يُخرج</b> أو <b>يُقدِّم</b>: مع منصوب الشخص، <r v=\"Acts.16.30\"></r> <r v=\"Acts.17.5\"></r>؛ عن الإحضار للمحاكمة، <r v=\"Acts.12.6\"></r>؛ يليه <g>ἐπί</g> مع مضاف إليه الشخص، <r v=\"Acts.25.26\"></r>.</s> <s n=\"2.\">لازم؛ <s n=\"(a)\"><b>يتقدّم في الطريق</b>، <r v=\"1Tim.1.18\"></r> (الترجمة المنقحة، الهامش)، ومن ثمَّ <b>يسبق</b>، <b>يتقدّم</b>: <r v=\"Luke.18.39\"></r>؛ عكس <g>ἀκολουθέω</g>، <r v=\"Mark.11.9\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.14.22\"></r>، <r v=\"Mark.6.45\"></r>، <r v=\"1Tim.5.24\"></r>، <r v=\"Heb.7.18\"></r>؛ مع منصوب الشخص، <r v=\"Matt.2.9\"></r> <r v=\"Matt.21.9\"></r>، <r v=\"Mark.10.32\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.21.31\"></r> <r v=\"Matt.26.32\"></r> <r v=\"Matt.28.7\"></r>، <r v=\"Mark.14.28\"></r> <r v=\"Mark.16.7\"></r>؛</s> <s n=\"(b)\"><b>يمضي قُدُمًا</b>، <b>يتعدّى</b> (<r v=\"Sir.20.27\"></r>): <r v=\"2John.1.9\"></r>.†</s> </s>","en":"<f><o>προ-άγω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.17.16\"></r> (<h n=\"H5066\">נגשׁ</h>), <r v=\"Wis.19.11\"></r>, al.;]</e> </et> <s n=\"1.\">prop. trans., <b>to lead on</b>, <b>lead forth</b> or <b>forward</b>: c. acc. pers., <r v=\"Acts.16.30\"></r> <r v=\"Acts.17.5\"></r>; of bringing forth to trial, <r v=\"Acts.12.6\"></r> (WH, txt., <g>προσάγ-</g>); seq. <g>ἐπί</g>, c. gen. pers., <r v=\"Acts.25.26\"></r>.</s> <s n=\"2.\">Intrans. (Plat., Polyb., and later writers; v. Bl., § 53, 1; MM, xxi); <s n=\"(a)\"><b>to lead the way</b>, <r v=\"1Tim.1.18\"></r> (R, mg.), hence, <b>to go before</b>, <b>precede</b>: <r v=\"Luke.18.39\"></r>; opp. to <g>ἀκολουθέω</g>, <r v=\"Mark.11.9\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.14.22\"></r>, <r v=\"Mark.6.45\"></r>, <r v=\"1Tim.5.24\"></r>, <r v=\"Heb.7.18\"></r>; c. acc. pers., <r v=\"Matt.2.9\"></r> <r v=\"Matt.21.9\"></r>, <r v=\"Mark.10.32\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.21.31\"></r> <r v=\"Matt.26.32\"></r> <r v=\"Matt.28.7\"></r>, <r v=\"Mark.14.28\"></r> <r v=\"Mark.16.7\"></r>;</s> <s n=\"(b)\"><b>to go on</b>, <b>advance</b> (<r v=\"Sir.20.27\"></r>): <r v=\"2John.1.9\"></r>.†</s> </s>"},"G4292":{"l":"προκαλέω","o":1,"ar":"<f>** <o>προ-καλέω</o>، <g>-ῶ</g>،</f> <s><b>دعا إلى الخروج</b>. وأكثر ما يأتي في الصيغة الوسطى، <s n=\"(a)\"><b>تحدّى</b>؛ ومن ثم <b>استفزّ، أغاظ</b>: <r v=\"Gal.5.26\"></r>؛</s> <s n=\"(b)\"><b>دعا</b> (<r v=\"2Macc.8.11\"></r>).†</s> </s>","en":"<f>** <o>προ-καλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.11\"></r> A*;]</e> </et> <s><b>to call forth</b>. Most freq. in mid., <s n=\"(a)\"><b>to challenge</b>; hence, <b>to provoke</b>: <r v=\"Gal.5.26\"></r>;</s> <s n=\"(b)\"><b>to invite</b> (<r v=\"2Macc.8.11\"></r>).†</s> </s>"},"G4288":{"l":"προθυμία","o":5,"ar":"<f>** <o>προθυμία</o>، <g>-ας, ἡ</g></f> <s><b>نشاط، رغبة</b>، <b>استعداد</b>: <r v=\"Acts.17.11\"></r>، <r v=\"2Cor.8.11\"></r>، <r v=\"2Cor.8.12\"></r>، <r v=\"2Cor.8.19\"></r>، <r v=\"2Cor.9.2\"></r>.†</s>","en":"<f>** <o>προθυμία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πρόθυμος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.45.23\"></r>*;]</e> </et> <s><b>eagerness</b>, <b>willingness</b>, <b>readiness</b>: <r v=\"Acts.17.11\"></r>, <r v=\"2Cor.8.11\"></r>, <r v=\"2Cor.8.12\"></r>, <r v=\"2Cor.8.19\"></r> <r v=\"2Cor.9.2\"></r>.†</s>"},"G4298":{"l":"προκόπτω","o":6,"ar":"<f>** <o>προ-κόπτω</o>،</f> <s><b>شقّ طريقًا إلى الأمام</b>، <b>تقدّم</b>، <b>مضى قُدُمًا</b>؛ (في اليونانية الكلاسيكية متعدٍّ مع صفة محايدة، مثل <g>οὐδὲν π., τὰ πολλὰ π.</g>)؛ وعند الكتّاب المتأخرين لازم تمامًا: <b>تقدّم</b>، <b>تناهى</b>: عن الزمن، <r v=\"Rom.13.12\"></r>. مجازيًا، <r v=\"Luke.2.52\"></r>، <r v=\"Gal.1.14\"></r>، <r v=\"2Tim.2.16\"></r>، <r v=\"2Tim.3.9\"></r>، <r v=\"2Tim.3.13\"></r>.†</s>","en":"<f>** <o>προ-κόπτω</o>,</f> <et> <e t=\"septuagint\">[in Sm.: <r v=\"Ps.45.5\"></r>*;]</e> </et> <s><b>to cut forward</b> a way, <b>forward</b>, <b>advance</b>, in cl. trans. with neut. adj., as <g>οὐδὲν π., τὰ πολλὰ π.</g> In late writers (Polyb., al.), wholly intrans., <b>to advance</b>, <b>progress</b>: of time, <r v=\"Rom.13.12\"></r>. Metaph., <r v=\"Luke.2.52\"></r>, <r v=\"Gal.1.14\"></r>, <r v=\"2Tim.2.16\"></r> <r v=\"2Tim.3.9\"></r>, <r v=\"2Tim.3.13\"></r>.†</s>"},"G4267":{"l":"προγινώσκω","o":5,"ar":"<f>** <o>προ-γινώσκω</o>،</f> <s><b>عرف من قبل</b>، <b>سبق فعرف</b>: <r v=\"2Pet.3.17\"></r>؛ مع منصوب الشخص، <r v=\"Acts.26.5\"></r>؛ عن علم الله السابق، <r v=\"Rom.8.29\"></r>، <r v=\"Rom.11.2\"></r>، <r v=\"1Pet.1.20\"></r>.†</s>","en":"<f>** <o>προ-γινώσκω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.6.13\"></r> <r v=\"Wis.8.8\"></r> <r v=\"Wis.18.6\"></r>*;]</e> </et> <s><b>to know beforehand</b>, <b>foreknow</b>: <r v=\"2Pet.3.17\"></r>; c. acc. pers., <r v=\"Acts.26.5\"></r>; of the Divine foreknowledge, <r v=\"Rom.8.29\"></r> <r v=\"Rom.11.2\"></r>, <r v=\"1Pet.1.20\"></r>.†</s>"},"G4299":{"l":"πρόκριμα","o":1,"ar":"<f>*† <o>πρό-κριμα</o>، <g>-τος, τό</g></f> <s><b>حكم مسبق</b>، <b>غرض، محاباة</b>: <r v=\"1Tim.5.21\"></r>.†</s>","en":"<f>*† <o>πρό-κριμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; cl. <g>προκρίνειν</g>, 1. <i>to prefer</i>. 2. <i>to judge beforehand</i>),</e> </et> <s><b>pre-judging</b>, <b>prejudice</b>: <r v=\"1Tim.5.21\"></r> (v. Cremer, 378).†</s>"},"G4285":{"l":"προηγέομαι","o":1,"ar":"<f><o>προ-ηγέομαι</o>،</f> <s n=\"1.\"><b>سبق، تقدّم</b> قائدًا (في الكلاسيكية مع المضاف إليه أو القابل): <r v=\"Rom.12.10\"></r>.</s> <s n=\"2.\">بمعنى لا يوجد في موضع آخر، <g>ἀλλήλους προηγούμενοι</g> = <g>ἀ. ἡγούμενοι ὑπερέχοντας</g>: <r v=\"Rom.12.10\"></r> (قارن <r v=\"1Thess.5.13\"></r>، <r v=\"Phil.2.3\"></r>، وفي الترجمات الإنجليزية: «<i>مقدِّمين</i>»).†</s>","en":"<f><o>προ-ηγέομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.20.9\"></r> (<h n=\"H1265\">בְּרוֹשׁ</h>), <r v=\"Prov.17.14\"></r> (<h n=\"H6440\">לִפְנֵי</h>), <r v=\"2Macc.4.40\"></r>, al.;]</e> </et> <s n=\"1.\"><b>to go before</b> as leader (in cl., c. gen., dat.): <r v=\"Rom.12.10\"></r> (Chrys., Vg., al.; v. <i>ICC</i>, in l.).</s> <s n=\"2.\">In a sense not elsewhere found, <g>ἀλλήλους προηγούμενοι</g> = <g>ἀ. ἡγούμενοι ὑπερέχοντας</g>: <r v=\"Rom.12.10\"></r> (<i>ICC</i>, cf. <r v=\"1Thess.5.13\"></r>, <r v=\"Phil.2.3\"></r> and EV \"<i>preferring</i>\").†</s>"},"G4251":{"l":"Πρίσκα","o":3,"ar":"<f><o>Πρίσκα</o>، <g>-ας, ἡ</g> (لاتيني)، و<g>Πρίσκιλλα, -ης, ἡ</g>،</f> <s><b>بريسكا</b>: <r v=\"Rom.16.3\"></r>، <r v=\"1Cor.16.19\"></r>، <r v=\"2Tim.4.19\"></r>؛ <b>بريسكلا</b>: <r v=\"Acts.18.2\"></r>، <r v=\"Acts.18.18\"></r>، <r v=\"Acts.18.26\"></r>؛ زوجة أكيلا، انظر تحت مدخل <g>Ἀκύλας</g>.†</s>","en":"<f><o>Πρίσκα</o>, <g>-ας, ἡ</g> (Lat.), and <g>Πρίσκιλλα, -ης, ἡ</g>,</f> <s><b>Prisca</b>: <r v=\"Rom.16.3\"></r>, <r v=\"1Cor.16.19\"></r>, <r v=\"2Tim.4.19\"></r>; <b>Priscilla</b>: <r v=\"Acts.18.2\"></r>, <r v=\"Acts.18.18\"></r>, <r v=\"Acts.18.26\"></r>; the wife of Aquila, v.s. <g>Ἀκύλας</g>.†</s>"},"G4255":{"l":"προαιρέω","o":1,"ar":"<f><o>προ-αιρέω</o>، <g>-ῶ</g>،</f> <s><b>أخرج</b> أو <b>قدّم</b>. وأكثر ما يكون في الصيغة الوسطى: <b>اختار</b>، <b>فضّل</b>، <b>نوى، عزم</b>: <r v=\"2Cor.9.7\"></r>.†</s>","en":"<f><o>προ-αιρέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: for <h n=\"H2836\">חשׁק</h>, etc.;]</e> </et> <s><b>to bring forth</b> or <b>forward</b>. Most freq. in mid., <b>to take by choice</b>, <b>prefer</b>, <b>propose</b>: <r v=\"2Cor.9.7\"></r>.†</s>"},"G4273":{"l":"προδότης","o":3,"ar":"<f>** <o>προ-δότης</o>، <g>-ου, ὁ</g></f> <s><b>مُسلِّم</b>، <b>خائن</b>: <r v=\"Luke.6.16\"></r>، <r v=\"Acts.7.52\"></r>، <r v=\"2Tim.3.4\"></r>.†</s>","en":"<f>** <o>προ-δότης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(<g>προδίδωμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.5.15\"></r> <r v=\"2Macc.10.13\"></r>, <r v=\"2Macc.10.22\"></r>, <r v=\"3Macc.3.24\"></r>*;]</e> </et> <s><b>a betrayer</b>, <b>traitor</b>: <r v=\"Luke.6.16\"></r>, <r v=\"Acts.7.52\"></r>, <r v=\"2Tim.3.4\"></r>.†</s>"},"G4247":{"l":"πρεσβῦτις","o":1,"ar":"<f>** <o>πρεσβῦτις</o>، <g>-ιδος, ἡ</g>، مؤنث <g>πρεσβύτης</g>،</f> <s><b>امرأة عجوز، متقدمة في السن</b>: <r v=\"Titus.2.3\"></r>.†</s>","en":"<f>** <o>πρεσβῦτις</o>, <g>-ιδος, ἡ</g>, fem, of <g>πρεσβύτης</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.16.14\"></r>*;]</e> </et> <s><b>an aged woman</b>: <r v=\"Titus.2.3\"></r>.†</s>"},"G4234":{"l":"πρᾶξις","o":6,"ar":"<f><o>πρᾶξις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>عمل</b>، <b>فعل</b>، تصرّف: <r v=\"Matt.16.27\"></r>؛ جمع، <g>π. ἀποσπτόλων</g>، عنوان سفر أعمال الرسل؛ وعند الكتّاب المتأخرين خاصةً عن الأعمال أو الممارسات الشريرة: <r v=\"Luke.23.51\"></r>؛ جمع، <r v=\"Rom.8.13\"></r>، <r v=\"Col.3.9\"></r>؛ مع الإشارة إلى السحر، <r v=\"Acts.19.18\"></r>.</s> <s n=\"2.\"><b>عمل</b>، <b>نشاط</b>، <b>شغل</b>، <b>وظيفة</b>: <r v=\"Rom.12.4\"></r>.†</s>","en":"<f><o>πρᾶξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πράσσω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.13.22\"></r> <r v=\"2Chr.27.7\"></r> <r v=\"2Chr.28.26\"></r> (<h n=\"H1870\">דֶּרֶךְ</h>), <r v=\"Job.24.5\"></r> A (<h n=\"H6467\">פֹּעַל</h>), <r v=\"Prov.13.13\"></r>, <r v=\"Wis.9.11\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a doing</b>, <b>deed</b>, act: <r v=\"Matt.16.27\"></r>; pl., <g>π. ἀποσπτόλων</g>, Ac, <i>tit.</i>; in late writers especially of wicked deeds or practices (freq. in Polyb.): <r v=\"Luke.23.51\"></r>; p1., <r v=\"Rom.8.13\"></r>, <r v=\"Col.3.9\"></r>; with ref. to magic (v. <i>BS</i>, 323<i>5</i>), <r v=\"Acts.19.18\"></r>.</s> <s n=\"2.\"><b>an acting</b>, <b>action</b>, <b>business</b>, <b>function</b>: <r v=\"Rom.12.4\"></r>.†</s>"},"G4200":{"l":"πορισμός","o":2,"ar":"<f>**† <o>πορισμός</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>تدبير، توفير</b>.</s> <s n=\"2.\"><b>وسيلة للربح</b>: <r v=\"1Tim.6.5\"></r>، <r v=\"1Tim.6.6\"></r>.† </s>","en":"<f>**† <o>πορισμός</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πορίζω</g>, <i>to procure</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.13.19\"></r> <r v=\"Wis.14.2\"></r>*;]</e> </et> <s n=\"1.\"><b>a providing</b>.</s> <s n=\"2.\"><b>a means of gain</b>: <r v=\"1Tim.6.5\"></r>, <r v=\"1Tim.6.6\"></r> (Polyb., al.).† </s>"},"G4227":{"l":"Πούδης","o":1,"ar":"<f><o>Πούδης</o></f> <s><b>بوديس</b>: <r v=\"2Tim.4.21\"></r>.†</s>","en":"<f><o>Πούδης</o></f> <et> <e t=\"derivation\">(in <g>π.</g>, gen. <g>-εντος</g>, v. Zorell, s.v.), <g>ὁ</g> (Latin),</e> </et> <s><b>Pudens</b>: <r v=\"2Tim.4.21\"></r>.†</s>"},"G4287":{"l":"προθέσμιος","o":1,"ar":"<f>** <o>προ-θέσμιος</o>، <g>-α, -ον</g>،</f> <s><b>معيَّن مسبقًا</b>. في القانون الأتيكي اسمًا (وهكذا دائمًا في اليونانية الكلاسيكية)، <g>ἡ π.</g> (أي <g>ἡμέρα</g>)، <b>يوم معيَّن مسبقًا</b>، <b>وقت محدَّد من قبل</b>: <r v=\"Gal.4.2\"></r>.†</s>","en":"<f>** <o>προ-θέσμιος</o>, <g>-α, -ον</g>,</f> <et> <e t=\"septuagint\">[in Sm.: <r v=\"Job.28.3\"></r>, <r v=\"Dan.9.26\"></r>*;]</e> </et> <s><b>appointed beforehand</b>. In Attic law, as subst. (so always in cl.), <g>ἡ π.</g> (sc. <g>ἡμέρα</g>), <b>a day appointed beforehand</b>, <b>a previously appointed time</b>: <r v=\"Gal.4.2\"></r>.†</s>"},"G4245":{"l":"πρέσβυς","o":66,"ar":"<f><o>πρέσβυς</o>، <g>-εως, ὁ</g>، صيغة شعرية لـ <g>πρεσβύτης</g> (انظره)،</f> <s><b>شيخ، رجل مسنّ</b>. صيغة التفضيل: <g>πρεσβύτερος</g>، <g>-α</g>، <g>-ον</g>، [في السبعينية غالبًا ترجمةً لـ <h n=\"H2204\">זָקֵן</h>؛] <s n=\"1.\">عن السن: <b>أكبر، أسنّ</b>: <g>ὁ νἱὸς ὁ π.</g>، <r v=\"Luke.15.25\"></r>؛ اسمًا، عكس <g>νεανίσκοι</g>، <r v=\"Acts.2.17\"></r>؛ وعكس <g>νεώτερος</g>، <r v=\"1Tim.5.1\"></r>، <r v=\"1Tim.5.2\"></r>؛ عن القادة الدينيين في الأزمنة الماضية، <r v=\"Matt.15.2\"></r>، <r v=\"Mark.7.3\"></r>، <r v=\"Mark.7.5\"></r>، <r v=\"Heb.11.2\"></r> (= <g>οἱ πατέρες</g>، <r v=\"Heb.1.1\"></r>).</s> <s n=\"2.\">عن المقام أو الرتبة أو الوظيفة؛ <s n=\"(a)\">عند اليهود: <r v=\"Matt.16.21\"></r>، <r v=\"Matt.26.47\"></r>، <r v=\"Matt.26.57\"></r>، <r v=\"Matt.27.3\"></r>، <r v=\"Matt.27.12\"></r>، <r v=\"Matt.27.20\"></r>، <r v=\"Matt.27.41\"></r>، <r v=\"Matt.28.12\"></r>، <r v=\"Mark.8.31\"></r>، <r v=\"Mark.11.27\"></r>، <r v=\"Mark.14.43\"></r>، <r v=\"Mark.14.53\"></r>، <r v=\"Mark.15.1\"></r>، <r v=\"Luke.7.3\"></r>، <r v=\"Luke.9.22\"></r>، <r v=\"Luke.20.1\"></r>، <r v=\"Luke.22.52\"></r>، <r v=\"John.8.9\"></r>، <r v=\"Acts.4.5\"></r>، <r v=\"Acts.4.8\"></r>، <r v=\"Acts.4.23\"></r>، <r v=\"Acts.6.12\"></r>، <r v=\"Acts.23.14\"></r>، <r v=\"Acts.24.1\"></r>؛ <g>τ. Ἰουνδαίων</g>، <r v=\"Acts.25.15\"></r>؛ <g>τ. λαοῦ</g>، <r v=\"Matt.21.23\"></r>، <r v=\"Matt.26.3\"></r>، <r v=\"Matt.27.1\"></r>؛</s> <s n=\"(b)\">عند المسيحيين: <r v=\"Acts.11.30\"></r>، <r v=\"Acts.14.23\"></r>، <r v=\"Acts.15.2\"></r>، <r v=\"Acts.15.4\"></r>، <r v=\"Acts.15.6\"></r>، <r v=\"Acts.15.22\"></r>، <r v=\"Acts.15.23\"></r>، <r v=\"Acts.16.4\"></r>، <r v=\"Acts.21.18\"></r>، <r v=\"1Tim.5.17\"></r>، <r v=\"1Tim.5.19\"></r>، <r v=\"Titus.1.5\"></r>، <r v=\"2John.1.1\"></r>، <r v=\"3John.1.1\"></r>، <r v=\"1Pet.5.1\"></r>، <r v=\"1Pet.5.5\"></r>؛ <g>τ. ἐκκλησίας</g>، <r v=\"Acts.20.17\"></r>، <r v=\"Jas.5.14\"></r>؛</s> <s n=\"(c)\">في رؤى سفر الرؤيا: <r v=\"Rev.4.4\"></r>، <r v=\"Rev.4.10\"></r>، <r v=\"Rev.5.5\"></r>، <r v=\"Rev.5.6\"></r>، <r v=\"Rev.5.8\"></r>، <r v=\"Rev.5.11\"></r>، <r v=\"Rev.5.14\"></r>، <r v=\"Rev.7.11\"></r>، <r v=\"Rev.7.13\"></r>، <r v=\"Rev.11.16\"></r>، <r v=\"Rev.14.3\"></r>، <r v=\"Rev.19.4\"></r>. (عن استعمال هذه الكلمة في العهد الجديد وعلاقتها بـ <g>ἐπίσκοπος</g>، انظره.) †</s> </s> </s>","en":"<f><o>πρέσβυς</o>, <g>-εως, ὁ</g>, poët. form of <g>πρεσβύτης</g> (q.v.),</f> <et> <e t=\"septuagint\">[in LXX (= <g>πρεσβευτής</g>, <i>an ambassador</i>): <r v=\"Num.21.20\"></r> (<r v=\"Num.21.21\"></r>), al. (<h n=\"H4397\">מַלְאָךְ</h>), <r v=\"Isa.13.8\"></r> <r v=\"Isa.57.9\"></r> (<h n=\"H6735\">צִיר</h>), <r v=\"1Macc.9.70\"></r>, al.;]</e> </et> <s><b>an old man</b>. Compar., <g>πρεσβύτερος</g>, <g>-α</g>, <g>-ον</g>, [in LXX chiefly for <h n=\"H2204\">זָקֵן</h>;] <s n=\"1.\">of age, <b>elder</b>: <g>ὁ νἱὸς ὁ π.</g>, <r v=\"Luke.15.25\"></r>; as subst., opp. to <g>νεανίσκοι</g>, <r v=\"Acts.2.17\"></r>; to <g>νεώτερος</g>, <r v=\"1Tim.5.1\"></r>, <r v=\"1Tim.5.2\"></r>; of the religious leaders of the past, <r v=\"Matt.15.2\"></r>, <r v=\"Mark.7.3\"></r>, <r v=\"Mark.7.5\"></r>, <r v=\"Heb.11.2\"></r> (= <g>οἱ πατέρες</g>, <r v=\"Heb.1.1\"></r>).</s> <s n=\"2.\">Of dignity, rank or office (as found in <g>π.</g> and Inscr. of civil and religious offices, including priesthood, in Asia Minor and in Egypt; v. Deiss., <i>BS</i>, 154 ff., 233 ff.; <i>LAE</i>, 373); <s n=\"(a)\">among Jews: <r v=\"Matt.16.21\"></r> <r v=\"Matt.26.47\"></r>, <r v=\"Matt.26.57\"></r> <r v=\"Matt.27.3\"></r>, <r v=\"Matt.27.12\"></r>, <r v=\"Matt.27.20\"></r>, <r v=\"Matt.27.41\"></r> <r v=\"Matt.28.12\"></r>, <r v=\"Mark.8.31\"></r> <r v=\"Mark.11.27\"></r> <r v=\"Mark.14.43\"></r>, <r v=\"Mark.14.53\"></r> <r v=\"Mark.15.1\"></r>, <r v=\"Luke.7.3\"></r> <r v=\"Luke.9.22\"></r> <r v=\"Luke.20.1\"></r> <r v=\"Luke.22.52\"></r>, <r v=\"John.8.9\"></r>, <r v=\"Acts.4.5\"></r>, <r v=\"Acts.4.8\"></r>, <r v=\"Acts.4.23\"></r> <r v=\"Acts.6.12\"></r> <r v=\"Acts.23.14\"></r> <r v=\"Acts.24.1\"></r>; <g>τ. Ἰουνδαίων</g>, <r v=\"Acts.25.15\"></r>; <g>τ. λαοῦ</g>, <r v=\"Matt.21.23\"></r> <r v=\"Matt.26.3\"></r> <r v=\"Matt.27.1\"></r>;</s> <s n=\"(b)\">among Christians: <r v=\"Acts.11.30\"></r> <r v=\"Acts.14.23\"></r> <r v=\"Acts.15.2\"></r>, <r v=\"Acts.15.4\"></r>, <r v=\"Acts.15.6\"></r>, <r v=\"Acts.15.22\"></r>, <r v=\"Acts.15.23\"></r> <r v=\"Acts.16.4\"></r> <r v=\"Acts.21.18\"></r>, <r v=\"1Tim.5.17\"></r>, <r v=\"1Tim.5.19\"></r>, <r v=\"Titus.1.5\"></r>, <r v=\"2John.1.1\"></r>, <r v=\"3John.1.1\"></r>, <r v=\"1Pet.5.1\"></r>, <r v=\"1Pet.5.5\"></r>; <g>τ. ἐκκλησίας</g>, <r v=\"Acts.20.17\"></r>, <r v=\"Jas.5.14\"></r>;</s> <s n=\"(c)\">in the visions of the Apocalypse: <r v=\"Rev.4.4\"></r>, <r v=\"Rev.4.10\"></r> <r v=\"Rev.5.5\"></r>, <r v=\"Rev.5.6\"></r>, <r v=\"Rev.5.8\"></r>, <r v=\"Rev.5.11\"></r>, <r v=\"Rev.5.14\"></r> <r v=\"Rev.7.11\"></r>, <r v=\"Rev.7.13\"></r> <r v=\"Rev.11.16\"></r> <r v=\"Rev.14.3\"></r> <r v=\"Rev.19.4\"></r>. (On the NT use of this word and its relation to <g>ἐπίσκοπος</g> (q.v.), cf. Lft., <i>Phl.</i>, 93 ff., 189 ff.; <i>CGT</i>, <i>Past. Epp.</i>, lvi ff.) †</s> </s> </s>"},"G4226":{"l":"ποῦ","o":52,"ar":"<f><o>ποῦ</o>،</f> ظرف استفهام، <s n=\"1.\">أصلاً: <b>أين؟</b>: <r v=\"Matt.2.2\"></r>، <r v=\"Matt.26.17\"></r>، <r v=\"Mark.14.12\"></r>، <r v=\"Mark.14.14\"></r>، <r v=\"Luke.17.17\"></r>، <r v=\"Luke.17.37\"></r>، <r v=\"Luke.22.9\"></r>، <r v=\"Luke.22.11\"></r>، <r v=\"John.1.39\"></r>، <r v=\"John.7.11\"></r>، <r v=\"John.8.10\"></r>، <r v=\"John.8.19\"></r>، <r v=\"John.9.12\"></r>، <r v=\"John.11.34\"></r>؛ <g>ποῦ</g> (<g>ἐστιν</g>)، للدلالة على أن المسؤول عنه لا وجود له، <r v=\"Luke.8.25\"></r>، <r v=\"Rom.3.27\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"1Cor.12.17\"></r>، <r v=\"1Cor.12.19\"></r>، <r v=\"1Cor.15.55\"></r>، <r v=\"Gal.4.15\"></r>، <r v=\"2Pet.3.4\"></r>؛ <g>ποῦ φανεῖται</g>، <r v=\"1Pet.4.18\"></r>.</s> <s n=\"2.\">= <g>ὅπου</g>: مع الإخباري، <r v=\"Matt.2.4\"></r>، <r v=\"Mark.15.47\"></r>، <r v=\"John.1.40\"></r>، <r v=\"John.11.57\"></r>، <r v=\"John.20.2\"></r>، <r v=\"John.20.13\"></r>، <r v=\"John.20.15\"></r>، <r v=\"Rev.2.13\"></r>؛ مع صيغة الاحتمال، <r v=\"Matt.8.20\"></r>، <r v=\"Luke.9.58\"></r>، <r v=\"Luke.12.17\"></r>.</s> <s n=\"3.\">في الكلام الدارج = <g>ποῖ</g>: <b>إلى أين</b>: في الأسئلة المباشرة، <r v=\"John.7.35\"></r>، <r v=\"John.9.12\"></r>، <r v=\"John.13.36\"></r>، <r v=\"John.16.5\"></r>؛ وفي الأسئلة غير المباشرة، <r v=\"John.3.8\"></r>، <r v=\"John.8.14\"></r>، <r v=\"John.12.35\"></r>، <r v=\"John.14.5\"></r>، <r v=\"Heb.11.8\"></r>، <r v=\"1John.2.11\"></r>.†</s>","en":"<f><o>ποῦ</o>,</f> interrog. adv., <et> <e t=\"septuagint\">[in LXX for <h n=\"H335\">אַי</h>, <h n=\"H346\">אַיֵּה</h>, <h n=\"H575\">אָנָה</h>;]</e> </et> <s n=\"1.\">prop., <b>where?</b>: <r v=\"Matt.2.2\"></r> <r v=\"Matt.26.17\"></r>, <r v=\"Mark.14.12\"></r>, <r v=\"Mark.14.14\"></r>, <r v=\"Luke.17.17\"></r>, <r v=\"Luke.17.37\"></r> <r v=\"Luke.22.9\"></r>, <r v=\"Luke.22.11\"></r>, <r v=\"John.1.39\"></r> <r v=\"John.7.11\"></r> <r v=\"John.8.10\"></r>, <r v=\"John.8.19\"></r> <r v=\"John.9.12\"></r> <r v=\"John.11.34\"></r>; <g>ποῦ</g> (<g>ἐστιν</g>), indicating that the subject in question is not to be found, <r v=\"Luke.8.25\"></r>, <r v=\"Rom.3.27\"></r>, <r v=\"1Cor.1.20\"></r> <r v=\"1Cor.12.17\"></r>, <r v=\"1Cor.12.19\"></r> <r v=\"1Cor.15.55\"></r>, <r v=\"Gal.4.15\"></r>, <r v=\"2Pet.3.4\"></r>; <g>ποῦ φανεῖται</g>, <r v=\"1Pet.4.18\"></r>.</s> <s n=\"2.\">= <g>ὅπου</g> (WM, 640; Bl., § 50, 5): c. indic., <r v=\"Matt.2.4\"></r>, <r v=\"Mark.15.47\"></r>, <r v=\"John.1.40\"></r> <r v=\"John.11.57\"></r> <r v=\"John.20.2\"></r>, <r v=\"John.20.13\"></r>, <r v=\"John.20.15\"></r>, <r v=\"Rev.2.13\"></r>; c. subjc., <r v=\"Matt.8.20\"></r>, <r v=\"Luke.9.58\"></r> <r v=\"Luke.12.17\"></r>.</s> <s n=\"3.\">In colloq. (as in Eng.) = <g>ποῖ</g>, <b>whither</b>: in direct questions, <r v=\"John.7.35\"></r> <r v=\"John.9.12\"></r> <r v=\"John.13.36\"></r> <r v=\"John.16.5\"></r>; in indir. quest., <r v=\"John.3.8\"></r> <r v=\"John.8.14\"></r> <r v=\"John.12.35\"></r> <r v=\"John.14.5\"></r>, <r v=\"Heb.11.8\"></r>, <r v=\"1John.2.11\"></r>.†</s>"},"G4215":{"l":"ποταμός","o":17,"ar":"<f><o>ποταμός</o>، <g>-οῦ, ὁ</g>،</f> <s><b>نهر</b>، <b>مجرى ماء</b>، <b>سيل</b>: <r v=\"Matt.3.5\"></r>، <r v=\"Matt.7.25\"></r>، <r v=\"Matt.7.27\"></r>، <r v=\"Mark.1.5\"></r>، <r v=\"Luke.6.48\"></r>، <r v=\"Luke.6.49\"></r>، <r v=\"Acts.16.13\"></r>، <r v=\"2Cor.11.26\"></r>، <r v=\"Rev.8.10\"></r>، <r v=\"Rev.9.14\"></r>، <r v=\"Rev.12.15\"></r>، <r v=\"Rev.12.16\"></r>، <r v=\"Rev.16.4\"></r>، <r v=\"Rev.16.12\"></r>، <r v=\"Rev.21.1\"></r>، <r v=\"Rev.21.2\"></r>. مجازيًا، في الجمع، <g>π. ὕδατος ζῶντος</g>، <r v=\"John.7.38\"></r>.†</s>","en":"<f><o>ποταμός</o>, <g>-οῦ, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5104\">נָהָר</h>, <h n=\"H2975\">יְאֹר</h>;]</e> </et> <s><b>a river</b>, <b>stream</b>, <b>torrent</b>: <r v=\"Matt.3.5\"></r> <r v=\"Matt.7.25\"></r>, <r v=\"Matt.7.27\"></r>, <r v=\"Mark.1.5\"></r>, <r v=\"Luke.6.48\"></r>, <r v=\"Luke.6.49\"></r>, <r v=\"Acts.16.13\"></r>, <r v=\"2Cor.11.26\"></r>, <r v=\"Rev.8.10\"></r> <r v=\"Rev.9.14\"></r> <r v=\"Rev.12.15\"></r>, <r v=\"Rev.12.16\"></r> <r v=\"Rev.16.4\"></r>, <r v=\"Rev.16.12\"></r> <r v=\"Rev.21.1\"></r>, <r v=\"Rev.21.2\"></r>. Fig., pl., <g>π. ὕδατος ζῶντος</g>, <r v=\"John.7.38\"></r>.†</s>"},"G4203":{"l":"πορνεύω","o":8,"ar":"<f><o>πορνεύω</o>،</f> <s n=\"1.\"><b>يبذل</b> جسده للدعارة بأجرة.</s> <s n=\"2.\"><b>يزني</b>: <r v=\"Mark.10.19\"></r>، <r v=\"1Cor.6.18\"></r>، <r v=\"1Cor.10.8\"></r>، <r v=\"Rev.2.14\"></r>، <r v=\"Rev.2.20\"></r>. مجازيًا (كما في السبعينية: <r v=\"1Chr.5.25\"></r>، <r v=\"Jer.3.6\"></r>، <r v=\"Hos.9.1\"></r>، وفي مواضع أخرى)، عن عبادة الأوثان، <r v=\"Rev.17.2\"></r>، <r v=\"Rev.18.3\"></r>، <r v=\"Rev.18.9\"></r> (قارن <g>ἐκ-πορνεύω</g>).†</s>","en":"<f><o>πορνεύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2181\">זנה</h>;]</e> </et> <s n=\"1.\"><b>to prostitute</b> the body for hire.</s> <s n=\"2.\"><b>to commit fornication</b>: <r v=\"Mark.10.19\"></r> (WH, mg), <r v=\"1Cor.6.18\"></r> <r v=\"1Cor.10.8\"></r>, <r v=\"Rev.2.14\"></r>, <r v=\"Rev.2.20\"></r>. Metaph. (as in LXX: <r v=\"1Chr.5.25\"></r>, <r v=\"Jer.3.6\"></r>, <r v=\"Hos.9.1\"></r>, al.), of idolatry (but v. Swete, <i>Ap.</i>, 180 f.), <r v=\"Rev.17.2\"></r> <r v=\"Rev.18.3\"></r>, <r v=\"Rev.18.9\"></r> (cf. <g>ἐκ-πορνεύω</g>).†</s>"},"G4256":{"l":"προαιτιάομαι","o":1,"ar":"<f>*† <o>προ-αιτιάομαι</o>، <g>-ῶμαι</g>،</f> <s><b>يتّهم</b> أو <b>يشتكي مسبقًا</b>: <r v=\"Rom.3.9\"></r> (ولا يرد في موضع آخر).†</s>","en":"<f>*† <o>προ-αιτιάομαι</o>, <g>-ῶμαι</g>,</f> <s><b>to accuse</b> or <b>charge beforehand</b>: <r v=\"Rom.3.9\"></r> (not elsewhere).†</s>"},"G4258":{"l":"προαμαρτάνω","o":2,"ar":"<f>*† <o>προ-αμαρτάνω</o>،</f> <s><b>يخطئ من قبل</b>: <r v=\"2Cor.12.21\"></r>، <r v=\"2Cor.13.2\"></r>.†</s>","en":"<f>*† <o>προ-αμαρτάνω</o>,</f> <s><b>to sin before</b>: <r v=\"2Cor.12.21\"></r> <r v=\"2Cor.13.2\"></r>.†</s>"},"G4257":{"l":"προακούω","o":1,"ar":"<f>* <o>προ-ακούω</o>،</f> <s><b>يسمع مسبقًا</b>: <r v=\"Col.1.5\"></r>.†</s>","en":"<f>* <o>προ-ακούω</o>,</f> <s><b>to hear beforehand</b>: <r v=\"Col.1.5\"></r> (v. Lft., in l.).†</s>"},"G4280":{"l":"προερέω","o":9,"ar":"<f><o>προ-ερέω</o>، <g>-ῶ</g>، انظر تحت مدخل <g>προεῖπον</g>.</f>","en":"<f><o>προ-ερέω</o>, <g>-ῶ</g>, v.s. <g>προεῖπον</g>.</f>"},"G4222":{"l":"ποτίζω","o":15,"ar":"<f><o>ποτίζω</o></f> <s><b>يسقي</b>: مع المنصوب للشخص، <r v=\"Matt.25.35\"></r>، <r v=\"Matt.25.37\"></r>، <r v=\"Matt.25.42\"></r> <r v=\"Matt.27.48\"></r>، <r v=\"Mark.15.36\"></r>، <r v=\"Luke.13.15\"></r>، <r v=\"Rom.12.20\"></r>؛ مع مفعولين منصوبين، <r v=\"Matt.10.42\"></r>، <r v=\"Mark.9.41\"></r>؛ مجازيًا، <g>γάλα</g>، <r v=\"1Cor.3.2\"></r>؛ <g>ἐκ τ. οἴνου</g>، <r v=\"Rev.14.8\"></r>؛ عن النباتات: <b>يسقي، يروي</b> (قارن <r v=\"Gen.13.10\"></r>)، مجازيًا، <r v=\"1Cor.3.6-1Cor.3.8\"></r>. مجازيًا (قارن <r v=\"Isa.29.10\"></r>، <r v=\"Sir.15.3\"></r>)، عن الروح القدس، <r v=\"1Cor.12.13\"></r>.†</s>","en":"<f><o>ποτίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>πότος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8248\">שׁקה</h> hi.;]</e> </et> <s><b>to give to drink</b>: c. acc. pers., <r v=\"Matt.25.35\"></r>, <r v=\"Matt.25.37\"></r>, <r v=\"Matt.25.42\"></r> <r v=\"Matt.27.48\"></r>, <r v=\"Mark.15.36\"></r>, <r v=\"Luke.13.15\"></r>, <r v=\"Rom.12.20\"></r>; c. dupl. acc., <r v=\"Matt.10.42\"></r>, <r v=\"Mark.9.41\"></r>; fig., <g>γάλα</g>, <r v=\"1Cor.3.2\"></r>; <g>ἐκ τ. οἴνου</g>, <r v=\"Rev.14.8\"></r>; of plants, <b>to water</b> (Xen., Strab., al.; <r v=\"Gen.13.10\"></r>), fig., <r v=\"1Cor.3.6-1Cor.3.8\"></r>. Metaph. (cf. <r v=\"Isa.29.10\"></r>, <r v=\"Sir.15.3\"></r>), of the Spirit, <r v=\"1Cor.12.13\"></r>.†</s>"},"G4289":{"l":"πρόθυμος","o":3,"ar":"<f><o>πρόθυμος</o>، <g>-ον</g>،</f> <s><b>راغب</b>، <b>مستعدّ</b>: <r v=\"Matt.26.41\"></r>، <r v=\"Mark.14.38\"></r>؛ المحايد، <g>τὸ π.</g> = <g>ἡ προθυμία</g> (قارن <r v=\"3Macc.5.26\"></r>)، <g>οὕτως τὸ κατ’ ἐμὲ</g> (= <g>τὸ ἐμὸν</g> في الكلاسيكية) <g>π.</g>، <r v=\"Rom.1.15\"></r>.†</s>","en":"<f><o>πρόθυμος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.28.21\"></r>, <r v=\"2Chr.29.31\"></r> (<h n=\"H5081\">נָדִיב</h>), <r v=\"Hab.1.8\"></r> (<h n=\"H2363\">חוּשׁ</h>), al.;]</e> </et> <s><b>willing</b>, <b>ready</b>: <r v=\"Matt.26.41\"></r>, <r v=\"Mark.14.38\"></r>; neut., <g>τὸ π.</g> = <g>ἡ προθυμία</g> (Thuc., al., <r v=\"3Macc.5.26\"></r>), <g>οὕτως τὸ κατ’ ἐμὲ</g> (= cl. <g>τὸ ἐμὸν</g>) <g>π.</g>, <r v=\"Rom.1.15\"></r> (but v. <i>ICC</i>, in l.).†</s>"},"G4293":{"l":"προκαταγγέλλω","o":2,"ar":"<f>*† <o>προ-κατ-αγγέλλω</o>،</f> <s><b>يُنبئ مسبقًا، يسبق فيُخبر</b>: مع المنصوب والمصدر، <r v=\"Acts.3.18\"></r>؛ يليه <g>περί</g>، <r v=\"Acts.7.52\"></r>.†</s>","en":"<f>*† <o>προ-κατ-αγγέλλω</o>,</f> <s><b>to announce beforehand</b>: c. acc. et inf., <r v=\"Acts.3.18\"></r>; seq. <g>περί</g>, <r v=\"Acts.7.52\"></r>.†</s>"},"G4294":{"l":"προκαταρτίζω","o":1,"ar":"<f>* <o>προ-κατ-αρτίζω</o>،</f> <s><b>يُهيّئ مسبقًا</b>: <r v=\"2Cor.9.5\"></r>.†</s>","en":"<f>* <o>προ-κατ-αρτίζω</o>,</f> <s><b>to make ready beforehand</b>: <r v=\"2Cor.9.5\"></r>.†</s>"},"G4277":{"l":"προεῖπον","o":null,"ar":"<f>** <o>προ-εῖπον</o>، الماضي البسيط الثاني من مضارع غير مستعمل (انظر تحت مدخل <g>εἶπον</g>)، والتام <g>-είρηκα</g> (<r v=\"3Macc.6.35\"></r>*)، المبني للمجهول <g>-είρημαι</g> (<r v=\"2Macc.2.32\"></r>، <r v=\"3Macc.1.26\"></r>، وفي مواضع أخرى)،</f> <s n=\"1.\"><b>قال قبلاً</b>، <b>سبق فقال</b>: <r v=\"Gal.1.9\"></r>، <r v=\"1Thess.4.6\"></r> (وعن الصيغة <g>-αμεν</g>)، <r v=\"Heb.4.7\"></r>؛ يليه <g>ὅτι</g>: <r v=\"2Cor.7.3\"></r>، <r v=\"2Cor.13.2\"></r>، <r v=\"Gal.5.21\"></r>؛ عن النبوة: <r v=\"Matt.24.25\"></r>، <r v=\"Mark.13.23\"></r>، <r v=\"Acts.1.16\"></r>، <r v=\"Rom.9.29\"></r>، <r v=\"2Pet.3.2\"></r>، <r v=\"Jude.1.17\"></r>.</s> <s n=\"2.\"><b>أعلن جهارًا</b>، <b>صرّح علانيةً</b> أو <b>بوضوح</b>: وهكذا في هامش الترجمة المنقحة في <r v=\"2Cor.13.2\"></r>، <r v=\"Gal.5.21\"></r>، <r v=\"1Thess.4.6\"></r> (قارن <g>προλέγω</g>؛ ولكن انظر أعلاه).†</s>","en":"<f>** <o>προ-εῖπον</o>, 2 aor. from unused Pres. (v.s. <g>εἶπον</g>, and pf., <g>-είρηκα</g> (<r v=\"3Macc.6.35\"></r>*), pass., <g>-είρημαι</g> (<r v=\"2Macc.2.32\"></r>, <r v=\"3Macc.1.26\"></r>, al.),</f> <s n=\"1.\"><b>to say before</b>: <r v=\"Gal.1.9\"></r>, <r v=\"1Thess.4.6\"></r> (on the form <g>-αμεν</g>, v. WH, <i>App.</i>, 164), <r v=\"Heb.4.7\"></r>; seq. <g>ὅτι</g>, <r v=\"2Cor.7.3\"></r> <r v=\"2Cor.13.2\"></r>, <r v=\"Gal.5.21\"></r>; of prophecy, <r v=\"Matt.24.25\"></r>, <r v=\"Mark.13.23\"></r>, <r v=\"Acts.1.16\"></r>, <r v=\"Rom.9.29\"></r>, <r v=\"2Pet.3.2\"></r>, <r v=\"Jude.1.17\"></r>.</s> <s n=\"2.\"><b>to proclaim publicly</b>, <b>declare openly</b> or <b>plainly</b> (cl.): so R, mg., in <r v=\"2Cor.13.2\"></r>, <r v=\"Gal.5.21\"></r>, <r v=\"1Thess.4.6\"></r> (cf. <g>προλέγω</g>; but v. supr., and cf. M, <i>Th.</i>, 38).†</s>"},"G4291":{"l":"προΐστημι","o":8,"ar":"<f><o>προ-ΐστημι</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: متعدٍّ في المستقبل والماضي البسيط الأول، والماضي البسيط الأول من الصيغة الوسطى: <b>وضع أمام</b>، <b>أقام على</b>.</s> <s n=\"2.\">لازم، في التام والماضي الأتم والماضي البسيط الثاني، والمضارع والماضي الناقص من الصيغة الوسطى؛ <s n=\"(a)\"><b>ترأّس</b>، <b>دبّر</b>، <b>حكم</b>: <r v=\"Rom.12.8\"></r>، <r v=\"1Tim.5.17\"></r>؛ مع المضاف إليه: <r v=\"1Thess.5.12\"></r>، <r v=\"1Tim.3.4\"></r>، <r v=\"1Tim.3.5\"></r>، <r v=\"1Tim.3.12\"></r>؛</s> <s n=\"(b)\"><b>اهتم بـ</b>، <b>واظب على</b>: مع المضاف إليه للشيء، <g>καλῶν ἔργων</g>: <r v=\"Titus.3.8\"></r>، <r v=\"Titus.3.14\"></r> (وفي هامش الترجمة المنقحة: <i>يمارسون أعمالاً شريفة</i>).†</s> </s>","en":"<f><o>προ-ΐστημι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.13.17\"></r>, <r v=\"Prov.23.5\"></r> <r v=\"Prov.26.17\"></r>, <r v=\"Isa.43.24\"></r>, <r v=\"Amos.6.10\"></r> (no proper Heb. equiv.), <r v=\"Bel.1.7\"></r>, <r v=\"1Macc.5.19\"></r>, <r v=\"4Macc.11.27\"></r>*;]</e> </et> <s n=\"1.\">trans. in fut., 1 aor., and mid. 1 aor., <b>to put before</b>, <b>set over</b> (Plat., al.).</s> <s n=\"2.\">Intrans., in pf., plpf., 2 aor. and mid. pres. and impf.; <s n=\"(a)\"><b>to preside</b>, <b>rule</b>, <b>govern</b>: <r v=\"Rom.12.8\"></r>, <r v=\"1Tim.5.17\"></r>; c. gen., <r v=\"1Thess.5.12\"></r>, <r v=\"1Tim.3.4\"></r>, <r v=\"1Tim.3.5\"></r>, <r v=\"1Tim.3.12\"></r>;</s> <s n=\"(b)\"><b>to direct</b>, <b>maintain</b>: c. gen. rei, <g>καλῶν ἔργων</g>, <r v=\"Titus.3.8\"></r>, <r v=\"Titus.3.14\"></r> (on R, mg., <i>profess honest occupations</i>, v. <i>CGT</i>, in l.; Field, <i>Notes</i>, 223 f.).†</s> </s>"},"G4204":{"l":"πόρνη","o":12,"ar":"<f><o>πόρνη</o>، <g>-ης, ἡ</g>،</f> <s><b>زانية</b>، <b>بغيّ</b>: <r v=\"Matt.21.31\"></r>، <r v=\"Matt.21.32\"></r>، <r v=\"Luke.15.30\"></r>، <r v=\"1Cor.6.15\"></r>، <r v=\"1Cor.6.16\"></r>، <r v=\"Heb.11.31\"></r>، <r v=\"Jas.2.25\"></r>. مجازيًا، عن بابل (أي روما): <r v=\"Rev.17.1\"></r>، <r v=\"Rev.17.5\"></r>، <r v=\"Rev.17.15\"></r>، <r v=\"Rev.17.16\"></r>، <r v=\"Rev.19.2\"></r>.†</s>","en":"<f><o>πόρνη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2181\">זוֹנָה</h>;]</e> </et> <s><b>a prostitute</b>, <b>harlot</b>: <r v=\"Matt.21.31\"></r>, <r v=\"Matt.21.32\"></r>, <r v=\"Luke.15.30\"></r>, <r v=\"1Cor.6.15\"></r>, <r v=\"1Cor.6.16\"></r>, <r v=\"Heb.11.31\"></r>, <r v=\"Jas.2.25\"></r>. Metaph. (v. Swete, <i>Ap.</i>, 180 f.), of Babylon (i.e. Rome): <r v=\"Rev.17.1\"></r>, <r v=\"Rev.17.5\"></r>, <r v=\"Rev.17.15\"></r>, <r v=\"Rev.17.16\"></r> <r v=\"Rev.19.2\"></r>.†</s>"},"G4271":{"l":"πρόδηλος","o":3,"ar":"<f>** <o>πρό-δηλος</o>، <g>-ον</g>،</f> <s n=\"1.\"><b>ظاهر من قبل</b>.</s> <s n=\"2.\"><b>واضح جليّ</b>: <r v=\"1Tim.5.24\"></r>، <r v=\"1Tim.5.25\"></r>، <r v=\"Heb.7.14\"></r>.†</s>","en":"<f>** <o>πρό-δηλος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.8.29\"></r>, <r v=\"2Macc.3.17\"></r> <r v=\"2Macc.14.39\"></r>*;]</e> </et> <s n=\"1.\"><b>evident beforehand</b>.</s> <s n=\"2.\"><b>clearly evident</b>: <r v=\"1Tim.5.24\"></r>, <r v=\"1Tim.5.25\"></r>, <r v=\"Heb.7.14\"></r>.†</s>"},"G4244":{"l":"πρεσβυτέριον","o":3,"ar":"<f>**† <o>πρεσβυτέριον</o>، <g>-ου, τό</g></f> <s><b>مجمع شيوخ</b>، <b>مشيخة</b>: عن السنهدريم (قارن <g>συνέδριον</g>)، <r v=\"Luke.22.66\"></r>، <r v=\"Acts.22.5\"></r>؛ عن شيوخ (قسوس) الكنيسة المسيحية، <r v=\"1Tim.4.14\"></r>.†</s>","en":"<f>**† <o>πρεσβυτέριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πρεσβύτερος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sus.1.50\"></r> A*;]</e> </et> <s><b>a body of elders</b>, <b>presbytery</b>: of the Sanhedrin (cf. <g>συνέδριον</g>), <r v=\"Luke.22.66\"></r>, <r v=\"Acts.22.5\"></r>; of Christian presbyters, <r v=\"1Tim.4.14\"></r>.†</s>"},"G4269":{"l":"πρόγονος","o":2,"ar":"<f>** <o>πρό-γονος</o>، <g>-ον</g></f> <s n=\"1.\"><b>مولود قبلُ</b>.</s> <s n=\"2.\">اسمًا، في الجمع، <g>οἱ π.</g>، <b>الأسلاف</b>، <b>الآباء الأولون</b>: <r v=\"2Tim.1.3\"></r>؛ عن الوالدين الأحياء، <r v=\"1Tim.5.4\"></r>.†</s>","en":"<f>** <o>πρό-γονος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>προγίνομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.4.17\"></r>, <r v=\"Sir.8.4\"></r>, al.;]</e> </et> <s n=\"1.\"><b>born before</b>.</s> <s n=\"2.\">As subst., in pl., <g>οἱ π.</g>, <b>ancestors</b>, <b>forefathers</b>: <r v=\"2Tim.1.3\"></r>; of living parents (so Plat.), <r v=\"1Tim.5.4\"></r>.†</s>"},"G4213":{"l":"πόσις","o":3,"ar":"<f><o>πόσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">أصلاً: <b>شُرب</b>: <r v=\"Rom.14.17\"></r>، <r v=\"Col.2.16\"></r>.</s> <s n=\"2.\">= <g>πόμα</g>: <b>شراب</b>: <r v=\"John.6.55\"></r> (قارن <g>βρῶσις</g>).†</s>","en":"<f><o>πόσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.1.10\"></r> (<h n=\"H4960\">מִשְׁתֶּה</h>)*;]</e> </et> <s n=\"1.\">prop., <b>drinking</b>: <r v=\"Rom.14.17\"></r>, <r v=\"Col.2.16\"></r> (v. Lft.; <i>ICC</i>, in l.).</s> <s n=\"2.\">= <g>πόμα</g>, <b>drink</b>: <r v=\"John.6.55\"></r> (cf. <g>βρῶσις</g>).†</s>"},"G4252":{"l":"Πρίσκιλλα","o":3,"ar":"<f><o>Πρίσκιλλα</o>، انظر تحت مدخل <g>Πρίσκα</g>.</f>","en":"<f><o>Πρίσκιλλα</o>, v.s. <g>Πρίσκα</g>.</f>"},"G4278":{"l":"προενάρχομαι","o":2,"ar":"<f>*† <o>προ-ενάρχομαι</o>،</f> <s><b>يبدأ قبلًا</b>: <r v=\"2Cor.8.6\"></r>؛ مع المنصوب، <g>τὸ θέλειν</g>، <r v=\"2Cor.8.10\"></r> (لم ترد في غير هذا الموضع).†</s>","en":"<f>*† <o>προ-ενάρχομαι</o>,</f> <s><b>to begin before</b>: <r v=\"2Cor.8.6\"></r>; c. acc., <g>τὸ θέλειν</g>, <r v=\"2Cor.8.10\"></r> (not elsewhere).†</s>"},"G4266":{"l":"προγίνομαι","o":1,"ar":"<f>** <o>προ-γίνομαι</o>،</f> <s><b>يحدث قبلًا</b>: اسم المفعول التام المبني للمجهول، <r v=\"Rom.3.25\"></r>.†</s>","en":"<f>** <o>προ-γίνομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.19.13\"></r> <h>א</h>A, <r v=\"2Macc.14.3\"></r> <r v=\"2Macc.15.8\"></r>*;]</e> </et> <s><b>to happen before</b>: pf. pass. ptcp., <r v=\"Rom.3.25\"></r>.†</s>"},"G4263":{"l":"πρόβατον","o":39,"ar":"<f><o>πρόβατον</o>، <g>-ου, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ماشية</b>، وخاصةً الماشية الصغيرة: <b>غنم</b> و<b>ماعز</b>.</s> <s n=\"2.\">في العهد الجديد: <b>خروف، شاة</b>: <r v=\"Matt.7.15\"></r>، <r v=\"Mark.6.34\"></r>، وفي مواضع أخرى؛ <g>πρόβατα σφαγῆς</g>، <r v=\"Rom.8.36\"></r><i>(السبعينية)</i>. مجازيًا، عن أتباع قائد أو سيد، وخاصةً عن الذين هم في رعاية الراعي الصالح: <r v=\"Matt.10.6\"></r> <r v=\"Matt.15.24\"></r> <r v=\"Matt.26.31\"></r><i>(السبعينية)</i>، <r v=\"Mark.14.27\"></r><i>(السبعينية)</i>، <r v=\"John.10.7\"></r>، <r v=\"John.10.8\"></r>، <r v=\"John.10.15\"></r>، <r v=\"John.10.16\"></r>، <r v=\"John.10.26\"></r>، <r v=\"John.10.27\"></r> <r v=\"John.21.16\"></r>، <r v=\"John.21.17\"></r>، <r v=\"Heb.13.20\"></r>؛ عكس <g>ἐρίφια</g>، <r v=\"Matt.25.33\"></r>.</s>","en":"<f><o>πρόβατον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>προβαίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6629\">צֹאן</h>, also for <h n=\"H7716\">שֶׂה</h>, more rarely for <h n=\"H3532\">כֶּבֶשׂ</h> (<h n=\"H3775\">כֶּשֶׂב</h>), <h n=\"H7353\">רָחֵל</h>;]</e> </et> <s n=\"1.\">in Hom., Hdt., <b>cattle</b>, esp. of small cattle, <b>sheep</b> and <b>goats</b>.</s> <s n=\"2.\">In NT, as in Attic writers generally (cf. MM, xxi), <b>a sheep</b>: <r v=\"Matt.7.15\"></r>, <r v=\"Mark.6.34\"></r>, al.; <g>πρόβατα σφαγῆς</g>, <r v=\"Rom.8.36\"></r><i>(LXX)</i>. Metaph. (in cl. of timidity, stupidity or idleness), of the followers of a leader or master, esp. of those who are subject to the care of the Good Shepherd: <r v=\"Matt.10.6\"></r> <r v=\"Matt.15.24\"></r> <r v=\"Matt.26.31\"></r><i>(LXX)</i>, <r v=\"Mark.14.27\"></r><i>(LXX)</i>, <r v=\"John.10.7\"></r>, <r v=\"John.10.8\"></r>, <r v=\"John.10.15\"></r>, <r v=\"John.10.16\"></r>, <r v=\"John.10.26\"></r>, <r v=\"John.10.27\"></r> <r v=\"John.21.16\"></r>, <r v=\"John.21.17\"></r> (WH txt., <g>προβάτια</g>), <r v=\"Heb.13.20\"></r>; opp. to <g>ἐρίφια</g>, <r v=\"Matt.25.33\"></r>.</s>"},"G4272":{"l":"προδίδωμι","o":1,"ar":"<f><o>προ-δίδωμι</o>،</f> <s n=\"1.\"><b>يعطي مسبقًا</b>، <b>يعطي أولاً</b>: <r v=\"Rom.11.35\"></r> (<r v=\"Job.41.2\"></r> (<r v=\"Job.41.11\"></r>) في السبعينية، وفي مواضع أخرى).</s> <s n=\"2.\"><b>يخون، يسلّم</b> (<r v=\"4Macc.4.1\"></r>).†</s>","en":"<f><o>προ-δίδωμι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.16.34\"></r> A (<h n=\"H5414\">נתן</h>), <r v=\"4Macc.4.1\"></r>, al.;]</e> </et> <s n=\"1.\"><b>to give before</b>, <b>give first</b>: <r v=\"Rom.11.35\"></r> (<r v=\"Job.41.2\"></r> (<r v=\"Job.41.11\"></r>) LXX, al.).</s> <s n=\"2.\"><b>to betray</b> (<r v=\"4Macc.4.1\"></r>).†</s>"},"G4221":{"l":"ποτήριον","o":31,"ar":"<f><o>ποτήριον</o>، <g>-ου, τό</g>، تصغير <g>ποτήρ</g></f> <s><b>كأس خمر</b>: <r v=\"Matt.23.25\"></r>، <r v=\"Matt.23.26\"></r> <r v=\"Matt.26.27\"></r>، <r v=\"Mark.7.4\"></r> <r v=\"Mark.14.23\"></r>، <r v=\"Luke.11.39\"></r> <r v=\"Luke.22.17\"></r>، <r v=\"Luke.22.20\"></r>، <r v=\"1Cor.11.25\"></r>، <r v=\"Rev.17.4\"></r>؛ <g>πίνειν ἐκ τοῦ π.</g>، <r v=\"1Cor.11.28\"></r>؛ مع المضاف إليه للشيء، <r v=\"Matt.10.42\"></r>، <r v=\"Mark.9.41\"></r>؛ <g>τ. εὐλογίας</g>، <r v=\"1Cor.10.16\"></r>؛ بالكناية، عن محتوى الكأس، <r v=\"Luke.22.20\"></r>، <r v=\"1Cor.11.25\"></r>، <r v=\"1Cor.11.26\"></r>؛ مع المضاف إليه للأشخاص، <r v=\"1Cor.10.21\"></r> <r v=\"1Cor.11.27\"></r>. مجازيًا، عن اختبار تدبير العناية الإلهية: عن الرخاء (<r v=\"Ps.16.5\"></r>، وفي مواضع أخرى)؛ عن الشدة (<r v=\"Ps.11.6\"></r>، <r v=\"Isa.51.17\"></r>، وفي مواضع أخرى): عن آلام المسيح، <r v=\"Matt.20.22\"></r>، <r v=\"Matt.20.23\"></r> <r v=\"Matt.26.39\"></r> <r v=\"Matt.10.38\"></r>، <r v=\"Matt.26.39\"></r> <r v=\"Matt.14.36\"></r>، <r v=\"Luke.22.42\"></r>، <r v=\"John.18.11\"></r>؛ عن العقاب الإلهي، <r v=\"Rev.14.10\"></r> <r v=\"Rev.16.19\"></r> <r v=\"Rev.18.6\"></r>.†</s>","en":"<f><o>ποτήριον</o>, <g>-ου, τό</g>, dimin. of <g>ποτήρ</g></f> <et> <e t=\"derivation\">(&lt; <g>πίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3563\">כּוֹס</h>;]</e> </et> <s><b>a wine cup</b>: <r v=\"Matt.23.25\"></r>, <r v=\"Matt.23.26\"></r> <r v=\"Matt.26.27\"></r>, <r v=\"Mark.7.4\"></r> <r v=\"Mark.14.23\"></r>, <r v=\"Luke.11.39\"></r> <r v=\"Luke.22.17\"></r>, <r v=\"Luke.22.20\"></r> (WH, R, mg., om.), <r v=\"1Cor.11.25\"></r>, <r v=\"Rev.17.4\"></r>; <g>πίνειν ἐκ τοῦ π.</g>, <r v=\"1Cor.11.28\"></r>; c. gen. rei, <r v=\"Matt.10.42\"></r>, <r v=\"Mark.9.41\"></r>; <g>τ. εὐλογίας</g>, <r v=\"1Cor.10.16\"></r>; by meton., of the contents of the cup, <r v=\"Luke.22.20\"></r> (WH, R, mg., om.), <r v=\"1Cor.11.25\"></r>, <r v=\"1Cor.11.26\"></r>; c. gen. pers., <r v=\"1Cor.10.21\"></r> <r v=\"1Cor.11.27\"></r>. Metaph., of experience of divine providence; of prosperity (<r v=\"Ps.16.5\"></r>, al.); of adversity (<r v=\"Ps.11.6\"></r>, <r v=\"Isa.51.17\"></r>, al.): of the sufferings of Christ, <r v=\"Matt.20.22\"></r>, <r v=\"Matt.20.23\"></r> <r v=\"Matt.26.39\"></r> <r v=\"Matt.10.38\"></r>, <r v=\"Matt.26.39\"></r> <r v=\"Matt.14.36\"></r>, <r v=\"Luke.22.42\"></r>, <r v=\"John.18.11\"></r>; of divine punishment, <r v=\"Rev.14.10\"></r> <r v=\"Rev.16.19\"></r> <r v=\"Rev.18.6\"></r>.†</s>"},"G4240":{"l":"πραΰτης","o":11,"ar":"<f><o>πραΰτης</o></f> <s><b>لطف</b>، <b>وداعة</b>: <r v=\"1Cor.4.21\"></r>، <r v=\"2Cor.10.1\"></r>، <r v=\"Gal.5.23\"></r> <r v=\"Gal.6.1\"></r>، <r v=\"Eph.4.2\"></r>، <r v=\"Col.3.12\"></r>، <r v=\"2Tim.2.25\"></r>، <r v=\"Titus.3.2\"></r>، <r v=\"Jas.1.21\"></r> <r v=\"Jas.3.13\"></r>، <r v=\"1Pet.3.15\"></r>.†</s>","en":"<f><o>πραΰτης</o></f> <et> <e t=\"derivation\">(Rec. <g>-ότης</g>, exc. <r v=\"Jas.1.21\"></r> <r v=\"Jas.3.13\"></r>, <r v=\"1Pet.3.15\"></r>, where <g>πρᾳύτης</g>), <g>-ητος, ἡ</g>, late form of <g>πραότης</g>,</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.45.4\"></r> <r v=\"Ps.90.10\"></r> <r v=\"Ps.132.1\"></r> (<h n=\"H6037\">עַנְוָה</h>, <h n=\"H6039\">עֻנּוֹת</h>, <r v=\"Ezra.5.1\"></r>, Si<i>6</i>*;]</e> </et> <s><b>gentleness</b>, <b>meekness</b>: <r v=\"1Cor.4.21\"></r>, <r v=\"2Cor.10.1\"></r>, <r v=\"Gal.5.23\"></r> <r v=\"Gal.6.1\"></r>, <r v=\"Eph.4.2\"></r>, <r v=\"Col.3.12\"></r> (v. Lft., in l.), <r v=\"2Tim.2.25\"></r>, <r v=\"Titus.3.2\"></r>, <r v=\"Jas.1.21\"></r> <r v=\"Jas.3.13\"></r>, <r v=\"1Pet.3.15\"></r>.†</s> <sy><i>SYN.</i>: <g>ἐπιεικία</g>, q.v.</sy>"},"G4209":{"l":"πορφύρα","o":4,"ar":"<f><o>πορφύρα</o>، <g>-ας, ἡ</g>،</f> <s n=\"1.\"><b>سمك الأرجوان</b> (الصدفة التي يُستخرج منها الصبغ) (قارن <r v=\"1Macc.4.23\"></r>).</s> <s n=\"2.\"><b>صبغ أرجواني</b>.</s> <s n=\"3.\">وفي الاستعمال المتأخر، = <g>πορφυρίς</g>، <b>ثوب أرجواني</b>: <r v=\"Mark.15.17\"></r>، <r v=\"Mark.15.20\"></r>، <r v=\"Luke.16.19\"></r>، <r v=\"Rev.18.12\"></r>.†</s>","en":"<f><o>πορφύρα</o>, <g>-ας, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H713\">אַרְגָּמָן</h>, <h n=\"H710\">אַרְגְּוָן</h>;]</e> </et> <s n=\"1.\"><b>the purple-fish</b> (cf. <r v=\"1Macc.4.23\"></r>).</s> <s n=\"2.\"><b>purple dye</b>.</s> <s n=\"3.\">Later, = <g>πορφυρίς</g>, <b>a purple garment</b>: <r v=\"Mark.15.17\"></r>, <r v=\"Mark.15.20\"></r>, <r v=\"Luke.16.19\"></r>, <r v=\"Rev.18.12\"></r>.†</s>"},"G4249":{"l":"πρίζω","o":1,"ar":"<f><o>πρίζω</o> = <g>πρίω</g>،</f> <s><b>نشر بالمنشار</b>، <b>نشر شطرين</b> (= <g>π. δίχα</g>): المبني للمجهول، <r v=\"Heb.11.37\"></r> (قارن <g>δια-πρίω</g>).†</s>","en":"<f><o>πρίζω</o> = <g>πρίω</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Amos.1.3\"></r>, <r v=\"Sus.1.59\"></r>*;]</e> </et> <s><b>to saw</b>, <b>saw asunder</b> (= <g>π. δίχα</g>, Thuc., iv, 100): pass, <r v=\"Heb.11.37\"></r> (cf. <g>δια-πρίω</g>).†</s>"},"G4216":{"l":"ποταμοφόρητος","o":1,"ar":"<f>*† <o>ποταμο-φόρητος</o>، <g>-ον</g>،</f> <s><b>جرفه السيل</b>: <r v=\"Rev.12.15\"></r>.†</s>","en":"<f>*† <o>ποταμο-φόρητος</o>, <g>-ον</g>,</f> <s><b>carried away by a stream</b>: <r v=\"Rev.12.15\"></r> (for two exx. in <g>π.</g>, v. MM, xxi).†</s>"},"G4207":{"l":"πόρρωθεν","o":2,"ar":"<f><o>πόρρωθεν</o>،</f> ظرف <s><b>من بعيد</b>: <r v=\"Luke.17.12\"></r>، <r v=\"Heb.11.13\"></r>.†</s>","en":"<f><o>πόρρωθεν</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>τόρρω</g>, q.v.),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7350\">מֵרָחוֹק</h> and cogn. forms;]</e> </et> <s><b>from afar</b>: <r v=\"Luke.17.12\"></r>, <r v=\"Heb.11.13\"></r>.†</s>"},"G4219":{"l":"πότε","o":19,"ar":"<f><o>πότε</o>،</f> ظرف استفهام للزمان، <s><b>متى؟</b>: <r v=\"Matt.25.37-Matt.25.39\"></r>، <r v=\"Matt.25.44\"></r>، <r v=\"Luke.21.7\"></r>، <r v=\"John.6.25\"></r>؛ <g>ἕως π.</g>، <b>إلى متى</b>: <r v=\"Matt.17.17\"></r>، <r v=\"Mark.9.19\"></r>، <r v=\"Luke.9.41\"></r>، <r v=\"John.10.24\"></r>، <r v=\"Rev.6.10\"></r>. وفي الأسئلة غير المباشرة، = <g>ὁπότε</g>، <r v=\"Matt.24.3\"></r>، <r v=\"Mark.13.4\"></r>، <r v=\"Mark.13.33\"></r>، <r v=\"Mark.13.35\"></r>، <r v=\"Luke.12.36\"></r> <r v=\"Luke.17.20\"></r>.†</s>","en":"<f><o>πότε</o>,</f> interrog. adv. of time, <s><b>when?</b>: <r v=\"Matt.25.37-Matt.25.39\"></r>, <r v=\"Matt.25.44\"></r>, <r v=\"Luke.21.7\"></r>, <r v=\"John.6.25\"></r>; <g>ἕως π.</g>, <b>how long</b>: <r v=\"Matt.17.17\"></r>, <r v=\"Mark.9.19\"></r>, <r v=\"Luke.9.41\"></r>, <r v=\"John.10.24\"></r>, <r v=\"Rev.6.10\"></r>. In indir. questions, = <g>ὁπότε</g>, <r v=\"Matt.24.3\"></r>, <r v=\"Mark.13.4\"></r>, <r v=\"Mark.13.33\"></r>, <r v=\"Mark.13.35\"></r>, <r v=\"Luke.12.36\"></r> <r v=\"Luke.17.20\"></r> (v. Bl., § 25, 4).†</s>"},"G4210":{"l":"πορφύρεος","o":4,"ar":"<f><o>πορφύρεος</o>، <g>-α, -ον</g>، بالإدغام، <g>-οῦς, -ᾶ, -οῦν</g></f> <s><b>أرجواني</b>: <r v=\"John.19.2\"></r>، <r v=\"John.19.5\"></r>؛ اسمًا، <g>πορφυροῦν</g> (أي <g>ἱμάτιον</g>)، <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.6\"></r>.†</s>","en":"<f><o>πορφύρεος</o>, <g>-α, -ον</g>, contr., <g>-οῦς, -ᾶ, -οῦν</g></f> <et> <e t=\"derivation\">(&lt; <g>πορφύρα</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H713\">אַרְגָּמָן</h>;]</e> </et> <s><b>purple</b>: <r v=\"John.19.2\"></r>, <r v=\"John.19.5\"></r>; as subst., <g>πορφυροῦν</g> (sc. <g>ἱμάτιον</g>), <r v=\"Rev.17.4\"></r> <r v=\"Rev.18.6\"></r>.†</s>"},"G4274":{"l":"πρόδρομος","o":1,"ar":"<f><o>πρό-δρομος</o>، <g>-ον</g></f> <s><b>راكض إلى الأمام</b>، <b>متقدّم</b>. اسمًا، <g>ὁ π.</g>، <b>طليعة</b>، <b>سابق</b>: <r v=\"Heb.6.20\"></r>.†</s>","en":"<f><o>πρό-δρομος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>προτρέχω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.13.21\"></r> (<r v=\"Num.13.20\"></r>), <r v=\"Isa.28.4\"></r> (<h n=\"H1061\">בּכר</h>), <r v=\"Wis.12.8\"></r>*;]</e> </et> <s><b>running forward</b>, <b>going in advance</b>. As subst., <g>ὁ π.</g>, <b>an advance guard</b>, <b>forerunner</b>: <r v=\"Heb.6.20\"></r>.†</s>"},"G4290":{"l":"προθύμως","o":1,"ar":"<f><o>προθύμως</o>،</f> <s><b>بنشاط</b>، <b>عن طيب خاطر</b>، <b>بنفس راغبة</b>: <r v=\"1Pet.5.2\"></r>.†</s>","en":"<f><o>προθύμως</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.29.34\"></r> (<h n=\"H3824\">לֵבָב</h> <h n=\"H3477\">יִשְׁרֵי</h>), <r v=\"Tob.7.8\"></r>, al.;]</e> </et> <s><b>eagerly</b>, <b>readily</b>, <b>with a ready mind</b>: <r v=\"1Pet.5.2\"></r>.†</s>"},"G4225":{"l":"πού","o":52,"ar":"<f><o>πού</o>،</f> أداة ملحقة (enclitic)، <s n=\"1.\"><b>في مكان ما</b>: <r v=\"Heb.2.6\"></r>، <r v=\"Heb.4.4\"></r>.</s> <s n=\"2.\"><b>إلى حدٍّ ما</b>، <b>ربما</b>، <b>نحو، تقريبًا</b>: <r v=\"Acts.27.29\"></r>، <r v=\"Rom.4.19\"></r>؛ <g>δή που</g>، <b>حقًّا، لا شك</b>: <r v=\"Heb.2.16\"></r>.†</s>","en":"<f><o>πού</o>,</f> enclitic particle, <s n=\"1.\"><b>anywhere</b>, <b>somewhere</b>: <r v=\"Heb.2.6\"></r> <r v=\"Heb.4.4\"></r>.</s> <s n=\"2.\"><b>in some degree</b>, <b>perhaps</b>, <b>about</b>: <r v=\"Acts.27.29\"></r> (T, <g>μήπου</g>), <r v=\"Rom.4.19\"></r>; <g>δή που</g> (T, <g>δήπου</g>), <b>surely</b>: <r v=\"Heb.2.16\"></r>.†</s>"},"G4268":{"l":"πρόγνωσις","o":2,"ar":"<f>**† <o>πρό-γνωσις</o>، <g>-εως, ἡ</g></f> <s><b>علم سابق</b>: <r v=\"Acts.2.23\"></r>، <r v=\"1Pet.1.2\"></r>.†</s>","en":"<f>**† <o>πρό-γνωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>προγινώσκω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.9.6\"></r> <r v=\"Jdt.11.19\"></r>*;]</e> </et> <s><b>foreknowledge</b>: <r v=\"Acts.2.23\"></r>, <r v=\"1Pet.1.2\"></r>.†</s>"},"G4265":{"l":"προβλέπω","o":1,"ar":"<f>† <o>προ-βλέπω</o>،</f> <s><b>سبق فرأى</b>، <b>سبق فنظر</b>: الصيغة الوسطى، <r v=\"Heb.11.40\"></r>.†</s>","en":"<f>† <o>προ-βλέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.37.13\"></r> (<h n=\"H7200\">ראה</h>)*;]</e> </et> <s><b>to foresee</b>: mid., <r v=\"Heb.11.40\"></r> (v. Bl., § 24, 55, 1).†</s>"},"G4239":{"l":"πραΰς","o":4,"ar":"<f><o>πραΰς</o>، <g>-εῖα</g>، <g>-ΰ</g>، و<g>πρᾷος</g></f> <s><b>وديع</b>، <b>حليم</b>: <r v=\"Matt.5.5\"></r>، <r v=\"Matt.11.29\"></r>، <r v=\"Matt.21.5\"></r><i>(السبعينية)</i>، <r v=\"1Pet.3.4\"></r>.†</s>","en":"<f><o>πραΰς</o>, <g>-εῖα</g>, <g>-ΰ</g>, and <g>πρᾷος</g></f> <et> <e t=\"derivation\">(or <g>πρᾶος</g>, v. Bl., § 3, 3), <g>-α</g>, <g>-ον</g> (v. LS, Thayer, s.v.),</e> <e t=\"septuagint\">[in LXX (always <g>-ΰς</g>, exc. <r v=\"2Macc.15.12\"></r>, <g>-ᾷος</g>, v. Thackeray, <i>Gr.</i>, 180 f.) for <h n=\"H6035\">עָנָו</h>, <h n=\"H6037\">עָנָיו</h>, <h n=\"H6041\">עָנִי</h>;]</e> </et> <s><b>gentle</b>, <b>meek</b>: <r v=\"Matt.5.5\"></r> <r v=\"Matt.11.29\"></r> <r v=\"Matt.21.5\"></r><i>(LXX)</i>, <r v=\"1Pet.3.4\"></r>.†</s>"},"G4217":{"l":"ποταπός","o":7,"ar":"<f>** <o>ποταπός</o></f> <s n=\"1.\">في اليونانية الكلاسيكية (= <g>ποδαπός</g>): <b>من أي بلد؟</b></s> <s n=\"2.\">عند الكتّاب المتأخرين = <g>ποῖος</g>: <b>أيّ نوع؟ ما هذا؟</b>: <r v=\"Matt.8.27\"></r>، <r v=\"Mark.13.1\"></r>، <r v=\"Luke.1.29\"></r> <r v=\"Luke.7.39\"></r>، <r v=\"2Pet.3.11\"></r>، <r v=\"1John.3.1\"></r>.†</s>","en":"<f>** <o>ποταπός</o></f> <et> <e t=\"derivation\">(late form of cl. <g>ποδ-</g>), <g>-ή, -όν</g>,</e> <e t=\"septuagint\">[in LXX: <r v=\"Sus.1.54\"></r>*;]</e> </et> <s n=\"1.\">(= <g>ποδαπός</g>) <b>from what country?</b></s> <s n=\"2.\">In late writers, = <g>ποῖος</g>, <b>of what sort?</b>: <r v=\"Matt.8.27\"></r>, <r v=\"Mark.13.1\"></r>, <r v=\"Luke.1.29\"></r> <r v=\"Luke.7.39\"></r>, <r v=\"2Pet.3.11\"></r>, <r v=\"1John.3.1\"></r>.†</s>"},"G4295":{"l":"πρόκειμαι","o":5,"ar":"<f><o>πρό-κειμαι</o>،</f> <s n=\"1.\"><b>يوضع أمام</b> المرء، <b>يُعرَض</b>: <r v=\"Heb.6.18\"></r> <r v=\"Heb.12.1\"></r>، <r v=\"Heb.12.2\"></r>، <r v=\"Jude.1.7\"></r>.</s> <s n=\"2.\"><b>يكون حاضرًا</b>، <b>يوجد</b>: <r v=\"2Cor.8.12\"></r>.†</s>","en":"<f><o>πρό-κειμαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.39.18\"></r> (<r v=\"Exod.39.36\"></r>), <r v=\"Num.4.7\"></r> (<h n=\"H6440\">פָּנִים</h>), etc.;]</e> <e t=\"derivation\">used as pass. of <g>προτίθημι</g>;</e> </et> <s n=\"1.\"><b>to be set before</b> one, <b>to be set forth</b>: <r v=\"Heb.6.18\"></r> <r v=\"Heb.12.1\"></r>, <r v=\"Heb.12.2\"></r>, <r v=\"Jude.1.7\"></r>.</s> <s n=\"2.\"><b>to present oneself</b>, <b>be present</b>: <r v=\"2Cor.8.12\"></r> (v. Mey., in l.).†</s>"},"G4224":{"l":"πότος","o":1,"ar":"<f><o>πότος</o>، <g>-ου, ὁ</g></f> <s><b>مجلس شُرب</b>، <b>منادمة (معاقرة الخمر)</b>: <r v=\"1Pet.4.3\"></r>.†</s>","en":"<f><o>πότος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4960\">מִשְׁתֶּה</h>;]</e> </et> <s><b>a drinking bout</b>, <b>carousal</b>: <r v=\"1Pet.4.3\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>κραιπάλη</g>.</sy>"},"G4231":{"l":"πραγματεύομαι","o":1,"ar":"<f><o>πραγματεύομαι</o></f> <s n=\"1.\"><b>انشغل</b>.</s> <s n=\"2.\"><b>اشتغل بالعمل</b>، خاصةً <b>تاجر</b>: <r v=\"Luke.19.13\"></r> (قارن <g>δια-πραγματεύομαι</g>).†</s>","en":"<f><o>πραγματεύομαι</o></f> <et> <e t=\"derivation\">(&lt; <g>πρᾶγμα</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.10.22\"></r> B, <r v=\"1Kgs.9.19\"></r> A (<h n=\"H2836\">חשׁק</h>), <r v=\"Dan.8.27\"></r> (<h n=\"H4399\">אֶת־מְלֶאכֶת</h> <h n=\"H6213\">עָשָׂה</h>)*;]</e> </et> <s n=\"1.\"><b>to busy oneself</b>.</s> <s n=\"2.\"><b>to be engaged in business</b>, esp. <b>to trade</b>: <r v=\"Luke.19.13\"></r> (cf. <g>δια-πραγματεύομαι</g>).†</s>"},"G4262":{"l":"προβατικός","o":1,"ar":"<f><o>προβατικός</o>، <g>-ή, -όν</g></f> <s><b>خاص بالغنم</b>: <g>ἡ π.</g> (والمقدَّر <g>πύλη</g>)، <b>باب الضأن</b>، <r v=\"John.5.2\"></r>.†</s>","en":"<f><o>προβατικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πρόβατον</g>),</e> <e t=\"septuagint\">[in LXX (<g>π. πύλη</g>): <r v=\"Neh.3.1\"></r>, <r v=\"Neh.3.32\"></r> <r v=\"Neh.12.39\"></r> (<h n=\"H6629\">צֹאן</h>)*;]</e> </et> <s><b>of sheep</b>: <g>ἡ π.</g> (sc. <g>πύλη</g>, v. supr.), <b>the sheep-gate</b>, <r v=\"John.5.2\"></r>.†</s>"},"G4223":{"l":"Ποτίολοι","o":1,"ar":"<f><o>Ποτίολοι</o>، <g>-ων, οἱ</g>،</f> <s><b>بوطيولي</b> (اليوم <i>بوتسوولي</i>)، مدينة على خليج نابولي: <r v=\"Acts.28.13\"></r>.†</s>","en":"<f><o>Ποτίολοι</o>, <g>-ων, οἱ</g>,</f> <s><b>Puteoli</b> (mod. <i>Pozzuoli</i>), a city on the Bay of Naples: <r v=\"Acts.28.13\"></r>.†</s>"},"G4206":{"l":"πόρρω","o":3,"ar":"<f><o>πόρρω</o>،</f> ظرف <s><b>بعيدًا</b>: <r v=\"Matt.15.8\"></r>، <r v=\"Mark.7.6\"></r><i>(السبعينية)</i>، <r v=\"Luke.14.32\"></r>؛ صيغة التفضيل، <g>πορρώτερον</g>، <r v=\"Luke.24.28\"></r>.†</s>","en":"<f><o>πόρρω</o>,</f> adv. <et> <e t=\"derivation\">(in older Attic, <g>πρόσω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7350\">רָחוֹק</h>, etc.;]</e> </et> <s><b>far off</b>: <r v=\"Matt.15.8\"></r>, <r v=\"Mark.7.6\"></r><i>(LXX)</i>, <r v=\"Luke.14.32\"></r>; comparat., <g>πορρώτερον</g> (<g>-ρω</g>, T), <r v=\"Luke.24.28\"></r>.†</s>"},"G4264":{"l":"προβιβάζω","o":1,"ar":"<f><o>προ-βιβάζω</o>، صيغة السببية من <g>προβαίνω</g>،</f> <s><b>يقود إلى الأمام</b>، <b>يدفع قُدُمًا</b>؛ مجازيًا، <b>يحمل على</b>، <b>يحرِّض</b>، <b>يحثّ</b>: <r v=\"Matt.14.8\"></r>.†</s>","en":"<f><o>προ-βιβάζω</o>, causal of <g>προβαίνω</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.35.34\"></r> (<h n=\"H3384\">ירה</h> hi.), <r v=\"Deut.6.7\"></r> (<h n=\"H8150\">שׁנן</h> pi.)*;]</e> </et> <s><b>to lead forward</b>, <b>lead on</b>; metaph., <b>to induce</b>, <b>incite</b>, <b>urge</b>: <r v=\"Matt.14.8\"></r>.†</s>"},"G4242":{"l":"πρεσβεία","o":2,"ar":"<f>** <o>πρεσβεία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>السن</b>، <b>الأقدمية</b>.</s> <s n=\"2.\"><b>الرتبة</b>، <b>المقام</b>.</s> <s n=\"3.\"><b>سفارة</b>؛ وكنايةً عن السفراء أنفسهم: <b>سفارة</b> (وفد): <r v=\"Luke.14.32\"></r> <r v=\"Luke.19.14\"></r>.†</s>","en":"<f>** <o>πρεσβεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πρεσβεύω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.4.11\"></r>*;]</e> </et> <s n=\"1.\"><b>age</b>, <b>seniority</b>.</s> <s n=\"2.\"><b>rank</b>, <b>dignity</b>.</s> <s n=\"3.\"><b>an embassy</b>; by meton., of the ambassadors, <b>embassy</b>: <r v=\"Luke.14.32\"></r> <r v=\"Luke.19.14\"></r>.†</s>"},"G4261":{"l":"προβάλλω","o":2,"ar":"<f><o>προ-βάλλω</o>،</f> <s n=\"1.\"><b>طرح أمام</b>.</s> <s n=\"2.\"><b>قدّم، دفع إلى الأمام</b>: مع المنصوب، <r v=\"Acts.19.33\"></r>؛ وعن الأشجار: <b>أفرخ</b>، <b>أخرج</b> (أي <g>φύλλα</g>)، <r v=\"Luke.21.30\"></r>.†</s>","en":"<f><o>προ-βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2330\">חוּד</h>, <h n=\"H4838\">מרק</h>, etc.;]</e> </et> <s n=\"1.\"><b>to throw before</b>.</s> <s n=\"2.\"><b>to put forward</b>: c. acc., <r v=\"Acts.19.33\"></r>; of trees, <b>to put forth</b>, <b>produce</b> (sc. <g>φύλλα</g>), <r v=\"Luke.21.30\"></r>.†</s>"},"G4296":{"l":"προκηρύσσω","o":1,"ar":"<f>* <o>προ-κηρύσσω</o>،</f> <s n=\"1.\"><b>أعلن بواسطة منادٍ</b>.</s> <s n=\"2.\">عمّن يقوم بعمل المنادي: <b>كرز، نادى</b>: <r v=\"Acts.13.24\"></r>.†</s>","en":"<f>* <o>προ-κηρύσσω</o>,</f> <s n=\"1.\"><b>to proclaim by herald</b>.</s> <s n=\"2.\">Of one who acts as a herald, <b>to proclaim</b>: <r v=\"Acts.13.24\"></r>.†</s>"},"G4212":{"l":"ποσάκις","o":3,"ar":"<f><o>ποσάκις</o>،</f> ظرف عددي استفهامي، <s><b>كم مرة</b>: <r v=\"Matt.18.21\"></r> <r v=\"Matt.23.37\"></r>، <r v=\"Luke.13.34\"></r>.†</s>","en":"<f><o>ποσάκις</o>,</f> interrog. num. adv., <s><b>how often</b>: <r v=\"Matt.18.21\"></r> <r v=\"Matt.23.37\"></r>, <r v=\"Luke.13.34\"></r>.†</s>"},"G4237":{"l":"πρασιά","o":2,"ar":"<f>** <o>πρασιά</o>، <g>-ᾶς, ἡ</g>،</f> <s><b>حوض زرع، مسكبة</b>؛ مجازيًا، عن صفوف أو جماعات منتظمة من الناس: <r v=\"Mark.6.40\"></r>.†</s>","en":"<f>** <o>πρασιά</o>, <g>-ᾶς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.24.31\"></r>*;]</e> </et> <s><b>a garden-bed</b>; metaph., of ranks or orderly groups of persons: <r v=\"Mark.6.40\"></r>.†</s>"},"G4259":{"l":"προαύλιον","o":1,"ar":"<f>* <o>προ-αύλιον</o>، <g>-ου, τό</g></f> <s><b>دهليز</b>، <b>رواق</b>: <r v=\"Mark.14.68\"></r>.†</s>","en":"<f>* <o>προ-αύλιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πρό</g>, <g>αὐλή</g>),</e> </et> <s><b>a porch</b>, <b>vestibule</b>: <r v=\"Mark.14.68\"></r>.†</s>"},"G4260":{"l":"προβαίνω","o":5,"ar":"<f><o>προ-βαίνω</o>،</f> <s><b>تقدّم</b>، <b>مضى</b>، <b>سار قُدُمًا</b>: <r v=\"Matt.4.21\"></r>، <r v=\"Mark.1.19\"></r>. مجازيًا، عن السن (<r v=\"Gen.18.11\"></r>، وفي مواضع أخرى)، <g>ἐν τ. ἡμέραις</g>، <r v=\"Luke.1.7\"></r>، <r v=\"Luke.1.18\"></r> <r v=\"Luke.2.36\"></r>.†</s>","en":"<f><o>προ-βαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H935\">בּוֹא</h>;]</e> </et> <s><b>to go forwards</b>, <b>go on</b>, <b>advance</b>: <r v=\"Matt.4.21\"></r>, <r v=\"Mark.1.19\"></r>. Metaph., of age (<r v=\"Gen.18.11\"></r>, al., Lys., Diod., al.), <g>ἐν τ. ἡμέραις</g>, <r v=\"Luke.1.7\"></r>, <r v=\"Luke.1.18\"></r> <r v=\"Luke.2.36\"></r>.†</s>"},"G4275":{"l":"προεῖδον","o":null,"ar":"<f><o>προ-εῖδον</o>، ماضٍ بسيط لا يُستعمل له مضارع (انظر تحت مدخل <g>προοράω</g>)،</f> <s><b>سبق فرأى</b>: <r v=\"Acts.2.31\"></r> (<g>προϊδών</g>)، <r v=\"Gal.3.8\"></r>.†</s>","en":"<f><o>προ-εῖδον</o>, aor. without pres. in use (v.s. <g>προοράω</g>),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.37.18\"></r> (<h n=\"H7200\">ראה</h>), <r v=\"Ps.139.3\"></r> (<h n=\"H5532\">סכן</h> hi.)*;]</e> </et> <s><b>to foresee</b>: <r v=\"Acts.2.31\"></r> (<g>προϊδών</g>; WH, <g>προιδών</g>), <r v=\"Gal.3.8\"></r>.†</s>"},"G4201":{"l":"Πόρκιος","o":1,"ar":"<f><o>Πόρκιος</o>، <g>-ου, ὁ</g>،</f> <s><b>بوركيوس</b>، الاسم الأول لبوركيوس فستوس (انظر تحت مدخل <g>Φῆστος</g>): <r v=\"Acts.24.27\"></r>.†</s>","en":"<f><o>Πόρκιος</o>, <g>-ου, ὁ</g>,</f> <s><b>Porcius</b>, prænomen of Porcius Festus (v.s. <g>Φῆστος</g>): <r v=\"Acts.24.27\"></r>.†</s>"},"G4248":{"l":"πρηνής","o":1,"ar":"<f>** <o>πρηνής</o>، <g>-ές</g></f> <s><b>مُنكَبًّا على وجهه</b>، <b>مُنطرحًا</b>: <r v=\"Acts.1.18\"></r>.†</s>","en":"<f>** <o>πρηνής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(in Att. also <g>πρανής</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.4.19\"></r>, <r v=\"3Macc.5.43\"></r>, <r v=\"3Macc.5.50\"></r> <r v=\"3Macc.6.23\"></r>*;]</e> </et> <s><b>headlong</b>, <b>prone</b>: <r v=\"Acts.1.18\"></r>.†</s>"},"G4233":{"l":"πράκτωρ","o":2,"ar":"<f><o>πράκτωρ</o>، <g>-ορος, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية (شعريًا): <b>الفاعل</b> أو <b>المنجِز</b>.</s> <s n=\"2.\">في أثينا، <b>من يستوفي المال المستحق</b>، <b>جابٍ</b>؛ ومن ثمّ عمومًا، <b>موظف</b> المحكمة: <r v=\"Luke.12.58\"></r>.†</s>","en":"<f><o>πράκτωρ</o>, <g>-ορος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πράσσω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.3.12\"></r> (<h n=\"H5066\">נֹגֵשׂ</h>)*;]</e> </et> <s n=\"1.\">(poët.) <b>one who does</b> or <b>accomplishes</b>.</s> <s n=\"2.\">In Athens, <b>one who exacts payment</b>, <b>a collector</b>; hence, generally (freq. in <g>π.</g>, v. Deiss., <i>BS</i>, 154), a court <b>officer</b>: <r v=\"Luke.12.58\"></r>.†</s>"},"G4211":{"l":"πορφυρόπωλις","o":1,"ar":"<f>*† <o>πορφυρόπωλις</o>، <g>-ιδος, ἡ</g>،</f> <s><b>بيّاعة أرجوان</b>: <r v=\"Acts.16.14\"></r>.†</s>","en":"<f>*† <o>πορφυρόπωλις</o>, <g>-ιδος, ἡ</g>,</f> <s><b>a seller of purple fabrics</b>: <r v=\"Acts.16.14\"></r>.†</s>"},"G4250":{"l":"πρίν","o":13,"ar":"<f><o>πρίν</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية والسبعينية: ظرف زمان، <b>قبلاً</b>، <b>سابقًا</b> (<r v=\"3Macc.5.28\"></r>، <r v=\"3Macc.6.4\"></r>، <r v=\"3Macc.6.31\"></r>).</s> <s n=\"2.\">أداة ربط، <b>قبل أن</b>؛ <s n=\"(a)\">بعد جملة مثبتة، مع المنصوب والمصدر: <r v=\"Matt.26.34\"></r>، <r v=\"Matt.26.75\"></r>، <r v=\"Mark.14.72\"></r>، <r v=\"Luke.22.61\"></r>، <r v=\"John.4.49\"></r>، <r v=\"John.8.58\"></r>، <r v=\"John.14.29\"></r>، <r v=\"Acts.2.20\"></r> <i>(السبعينية)</i>؛ <g>πρὶν ἤ</g>، <r v=\"Matt.1.18\"></r>، <r v=\"Mark.14.30\"></r>، <r v=\"Acts.2.20\"></r>، <r v=\"Acts.7.2\"></r>؛</s> <s n=\"(b)\">بعد جملة منفية، <g>πρὶν ἤ</g>: مع صيغة الاحتمال (يليه <g>ἄν</g>)، <r v=\"Luke.2.26\"></r>؛ مع صيغة التمني، <r v=\"Acts.25.16\"></r>.†</s> </s>","en":"<f><o>πρίν</o>,</f> <s n=\"1.\">as adv. of time, <b>before</b>, <b>formerly</b> (cl.; <r v=\"3Macc.5.28\"></r> <r v=\"3Macc.6.4\"></r>, <r v=\"3Macc.6.31\"></r>).</s> <s n=\"2.\">As conjc. (cl.), <b>before</b>; <s n=\"(a)\">after a positive sentence, c. acc. et inf.: <r v=\"Matt.26.34\"></r>, <r v=\"Matt.26.75\"></r>, <r v=\"Mark.14.72\"></r>, <r v=\"Luke.22.61\"></r>, <r v=\"John.4.49\"></r> <r v=\"John.8.58\"></r> (where D. om. <g>γενέσθαι</g> and <g>π.</g> becomes prep. c. gen.; v. Bl., § 69, 7) <r v=\"John.14.29\"></r>, <r v=\"Acts.2.20\"></r><i>(LXX)</i>, WH, txt.; <g>πρὶν ἤ</g> (not such good Attic in this construction; v. Bl., § 69, 7), <r v=\"Matt.1.18\"></r>, <r v=\"Mark.14.30\"></r>, <r v=\"Acts.2.20\"></r>, WH, mg., <r v=\"Acts.7.2\"></r>;</s> <s n=\"(b)\">after a negative sentence, <g>πρὶν ἤ</g>: a. subjc. (seq. <g>ἄν</g>, M, <i>Pr.</i>, 169), <r v=\"Luke.2.26\"></r>; c. optat., <r v=\"Acts.25.16\"></r>.†</s> </s>"}});A.got[42]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});